GimCorpus.put(139,0,[[1,1,"נְבוּאַת זְכַרְיָה סְתוּמָה הִיא מְאֹד, כִּי יֵשׁ בָּהּ מַרְאוֹת דּוֹמוֹת לַחֲלוֹם הַנִּתָּן לְפִתְרוֹן, וְאֵין אָנוּ יְכוֹלִים לַעֲמֹד עַל אֲמִתַּת פִּתְרוֹנוֹ עַד יָבֹא מוֹרֶה צֶדֶק (הושע י:יב). וּלְפִי הַיְּכֹלֶת אֶתֵּן לֵב לְיַשֵּׁב הַמִּקְרָאוֹת אֶחָד אֶחָד מִן הַפִּתְרוֹנוֹת הַדּוֹמוֹת לוֹ, וְאַחַר פִּתְרוֹנוֹת שֶׁל יוֹנָתָן:",1,0],[1,1,"בַּחֹדֶשׁ הַשְּׁמִינִי. קֹדֶם שֶׁהִתְחִילוּ לַחֲזוֹר וְלִבְנוֹת בַּמְּלָאכָה, שֶׁהֲרֵי בְּעֶשְׂרִים וְאַרְבָּעָה לַחֹדֶשׁ הִתְחִילוּ בָּהּ:",2,0],[1,2,"עַל אֲבוֹתֵיכֶם. שֶׁבְּדוֹר חֻרְבַּן הַבַּיִת:",1,0],[1,5,"אֲבוֹתֵיכֶם אַיֵּה הֵם. רְאוּ שֶׁלָּקוּ מַכָּה רָעָה בָּרָעָב בַּחֶרֶב וּבַשֶּׁבִי:",1,0],[1,5,"וְהַנְּבִיאִים הַלְעוֹלָם יִחְיוּ. וְאִם תֹּאמַר: אַף הַנְּבִיאִים אַיֵּה הֵם, הֲרֵי מֵתוּ? אֲנִי מֵשִׁיב לָכֶם: וְכִי הַנְּבִיאִים הָיָה לָהֶם לְעוֹלָם לִחְיוֹת? אַךְ סוֹפָן מוֹכִיחַ כִּי אֱמֶת הָיָה דִּבְרֵיהֶם, שֶׁכָּל דְּבָרַי וְחֻקַּי גְּזֵרוֹת פֻּרְעָנוּתִי אֲשֶׁר צִוִּיתִי אֶת עֲבָדַי הַנְּבִיאִים עֲלֵיכֶם, הֲלֹא הִשִּׂיגוּ אֲבֹתֵיכֶם.",2,0],[1,8,"רָאִיתִי הַלַּיְלָה וְגוֹ׳. רַבּוֹתֵינוּ פֵּרְשׁוּ מַה שֶּׁפֵּרְשׁוּ בְּאַגָּדַת חֵלֶק (סנהדרין צג.), אַךְ אֵין סֵדֶר הַפָּרָשָׁה וְהַלָּשׁוֹן מִתְיַשֵּׁב בּוֹ:",1,0],[1,8,"וְהִנֵּה אִישׁ. מַלְאָךְ:",2,0],[1,8,"עַל סוּס אָדֹם. רֶמֶז הוּא לִפָּרַע מִכַּשְׂדִּים מִמָּדַי וּפָרַס בַּחֶרֶב וּבַדָּם, כְּמוֹ שֶׁהוּא אוֹמֵר כָּאן ״וְקֶצֶף גָּדוֹל אֲנִי קֹצֵף עַל הָגּוֹיִם״:",3,0],[1,8,"וְאַחֲרָיו סוּסִים אֲדֻמִּים וְגוֹ׳. מוּכָנִים לִשְׁלִיחוּתוֹ שֶׁל מָקוֹם, וְיֵשׁ בָּהֶם מִינֵי צְבָעִים הַרְבֵּה, וְשֶׁבַח הוּא לוֹ. שְׂרֻקִּים. לֹא יָדַעְתִּי מַה צֶבַע הוּא, וְיוֹנָתָן תִּרְגֵּם: ״קְוָוחִין״:",4,0],[1,8,"בֵּין הַהֲדַסִּים אֲשֶׁר בַּמְּצוּלָה. בֵּין אִילָנֵי דְהַדַסַּיָּא דִּבְבָבֶל (סנהדרין צג.):",5,0],[1,9,"וָאֹמַר. לַמַּלְאָךְ אֶחָד אֲשֶׁר הָיָה מַרְאֶה אוֹתִי כָּל זֹאת מָה אֵלֶּה אֲדֹנִי. וְהוּא הָרוֹכֵב עַל סוּס אָדֹם (זכריה א:ח):",1,0],[1,10,"לְהִתְהַלֵּךְ בָּאָרֶץ. לִרְאוֹת אֶת שַׁלְוַת הָעַוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[1,12,"וַיַּעַן מַלְאַךְ ה׳. הוּא הַדּוֹבֵר בִּי:",1,0],[1,13,"וַיַּעַן ה׳ אֶת הַמַּלְאָךְ הַדּוֹבֵר בִּי דְּבָרִים טוֹבִים. לֹא שֶׁשָּׁמַע הַנָּבִיא מַה עָנָה, אַךְ מִמַּה שֶּׁאָמַר הַמַּלְאָךְ לוֹ ״קְרָא לֵאמֹר קִנֵּאתִי וְגוֹ׳״, אֲנִי יוֹדֵעַ שֶׁדְּבָרִים טוֹבִים עָנָהוּ:",1,0],[1,14,"קִנֵּאתִי לְצִיּוֹן. ״מִתְפָּרַע אֲנָא פּוּרְעָנוּת דִּין יְרוּשָׁלַיִם מִן הַמְּצִיקִים לָהּ״:",1,0],[1,15,"הַשַּׁאֲנַנִּים. אֲשֶׁר אֵלּוּ אוֹמְרִים עֲלֵיהֶם, שֶׁהֵם יוֹשְׁבִים וּשְׁקֵטִים:",1,0],[1,15,"אֲשֶׁר אֲנִי קָצַפְתִּי. עַל עַמִּי מְעָט:",2,0],[1,15,"וְהֵמָּה עָזְרוּ. עַל הַקֶּצֶף לְרָעָה:",3,0],[1,16,"וְקָו יִנָּטֶה. לָמֹד חוֹמוֹתֶיהָ אָרְכָּהּ וְרָחְבָּהּ:",1,0],[2,2,"אֵלֶּה הַקְּרָנוֹת. אֵלֶּה הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר בְּאַרְבַּע רוּחוֹת הַשָּׁמַיִם, אֲשֶׁר נָגְחוּ בְּקַרְנֵיהֶם אֶת יְהוּדָה וִירוּשָׁלִַם, עַד אֲשֶׁר זֵרוּם:",1,0],[2,3,"אַרְבָּעָה חָרָשִׁים. נַגָּרִים הַיּוֹדְעִים לְנַסֵּר אֶת הַקְּרָנוֹת. וְרַבּוֹתֵינוּ פֵּרְשׁוּ בְּמַסֶּכֶת סֻכָּה (סוכה נב:) מִי הֵם:",1,0],[2,4,"וָאֹמַר מָה. אֵלֶּה הַקְּרָנוֹת אֲשֶׁר רָאִיתִי בָּרִאשׁוֹנָה:",1,0],[2,4,"אֲשֶׁר זֵרוּ אֶת יְהוּדָה. וְהִשְׁפִּילוּם, עַד כְּפִי אִישׁ לֹא נָשָׂא רֹאשׁוֹ. וְלֹא נָתְנוּ לְאֶחָד מִבְּנֵי עַמִּי לְהָרִים רֹאשׁ:",2,0],[2,4,"וַיָּבֹאוּ אֵלֶּה. הֶחָרָשִׁים לְהַחֲרִיד אוֹתָן הַקְּרָנוֹת וּלְיַדּוֹת אוֹתָן:",3,0],[2,4,"לְיַדּוֹת. לְהַשְׁלִיךְ:",4,0],[2,5,"חֶבֶל מִדָּה. חוּט הַמִּדָּה לִמְדֹּד אֶת יְרוּשָׁלַיִם כַּמָּה יִהְיֶה אָרְכָּהּ וְרָחְבָּהּ:",1,0],[2,7,"וְהִנֵּה הַמַּלְאָךְ הַדֹּבֵר בִּי יוֹצֵא. הוּא אֲשֶׁר בְּיָדוֹ חֶבֶל הַמִּדָּה:",1,0],[2,8,"רוּץ דַּבֵּר אֶל הַנַּעַר. אַל תֵּצֵא עוֹד לָמֹד, כִּי נִמְלַךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּפַמַלְיָא שֶׁלּוֹ, שֶׁלֹּא יְהֵא לָהּ קֶצֶב וְשִׁעוּר (בבא בתרא עה:). וְעַתָּה רוּץ דַּבֵּר אֶל זְכַרְיָה לֵאמֹר פְּרָזוֹת תֵּשֵׁב – מֵאֵין חוֹמָה, כְּדֵי שֶׁיִּתְיַשְּׁבוּ בָהּ כָּל הַבָּא, וְתִגְדַּל מִיּוֹם אֶל יוֹם:",1,0],[2,9,"וַאֲנִי אֶהְיֶה לָּהּ. לְמָגֵן כְּאִלּוּ חוֹמַת אֵשׁ סָבִיב לָהּ, וְגַם בְּתוֹכָהּ תִּשְׁכֹּן שְׁכִינָתִי לִכְבוֹדְכֶם:",1,0],[2,10,"הוֹי הוֹי. אֵין הוֹי אֶלָּא לְשׁוֹן הַכְרָזָה וְהַזְעָקַת קִבּוּץ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״אַכְלוּ לְמַבְדְּרַיָּא״ – הַכְרִיזוּ, כְּמוֹ יַרְעֵם מִן שָׁמַיִם (שמואל ב כב:יד) – ״אַכְלוּ מִן שְׁמַיָּא״:",1,0],[2,10,"וְנֻסוּ מֵאֶרֶץ. צְאוּ גָּלֻיּוֹת עַמִּי מִתּוֹךְ בָּבֶל וְאַשּׁוּר:",2,0],[2,11,"הוֹי צִיּוֹן הִמָּלְטִי. אַף זֶה לְשׁוֹן הַכְרָזָה: הֵאָסְפוּ עַם גָּלוּת צִיּוֹן וְהִמָּלְטוּ מִתּוֹךְ בָּבֶל.",1,0],[2,12,"אַחַר כָּבוֹד. אַחַר כְּבוֹדְכֶם אֲנִי שָׁלוּחַ לְהַגְדִּיל לָכֶם כָּבוֹד. וּמִדְרַשׁ אַגָּדָה (תנחומא בובר, דברים ד): אַחַר כָּבוֹד – אַחַר שֶׁאֲשַׁלֵּם לְעֵשָׂו כָּבוֹד שֶׁכִּבֵּד אֶת אָבִיו:",1,0],[2,13,"וְהָיוּ שָׁלָל לְעַבְדֵיהֶם. לְיִשְׂרָאֵל, שֶׁהֵם עַתָּה עֲבָדִים לָהֶן:",1,0],[2,15,"וְנִלְווּ. וְנִתְחַבְּרוּ:",1,0],[2,16,"וְנָחַל ה׳ אֶת יְהוּדָה. לְנַחֲלָתוֹ וּלְחֶלְקוֹ:",1,0],[2,17,"הַס כָּל בָּשָׂר. כָּל שְׁאָר הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[2,17,"כִּי נֵעוֹר. לְשׁוֹן הֶעָרָה וְהַקָּצָה (תהלים לה:כג):",2,0],[3,1,"לְשִׂטְנוֹ. לְהַשְׂטִינוֹ, עַל שֶׁהָיוּ בָּנָיו נְשׂוּאִים נָשִׁים נָכְרִיּוֹת, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר עֶזְרָא: ״וַיִּמָּצֵא מִבְּנֵי הַכֹּהֲנִים אֲשֶׁר הוֹשִׁיבוּ נָשִׁים נָכְרִיּוֹת מִבְּנֵי יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק״ (עזרא י:יח):",1,0],[3,2,"יִגְעַר ה׳ בְּךָ הַשָּׂטָן. יִגְעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּךָ אַתָּה הַשָּׂטָן, וְחוֹזֵר וְאוֹמֵר וְיִגְעַר ה׳ בְּךָ הוּא הַבֹּחֵר בִּירוּשָׁלִָם, שֶׁלֹּא תִּכָּנֵס לְפָנָיו לְקַטְרֵג עַל הַצַּדִּיק הַזֶּה. הֲלֹא רָאוּי הוּא וְזָכָה לְכָךְ שֶׁהֻצַּל מֵאֵשׁ הַשְּׂרֵפָה:",1,0],[3,2,"הֲלֹא זֶה אוּד מֻצָּל מֵאֵשׁ. מְפֹרָשׁ בְּאַגָּדַת חֵלֶק (סנהדרין צג.) שֶׁהֻשְׁלַךְ עִם אַחְאָב בֶּן קוֹלָיָה וַחֲבֵרוֹ לָאוּר:",2,0],[3,3,"לָבוּשׁ בְּגָדִים צוֹאִים. כְּתַרְגּוּמוֹ: ״הֲווֹ לֵיהּ בְּנִין דְּנָסְבִין לְהוֹן נְשִׁין דְּלָא כַשְׁרִין לִכְהוּנְתָא״, וְהָיָה נֶעֱנָשׁ הוּא עַל שֶׁלֹּא מִיחָה בְּיָדָם (סנהדרין צג.):",1,0],[3,4,"הָסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו. יַבְדִּילוּ בָּנָיו אֶת נְשׁוֹתֵיהֶם, וְיִמְחוֹל לוֹ:",1,0],[3,4,"מַחֲלָצוֹת. חֲלִיפוֹת בְּגָדִים נָאִים, כְּלוֹמַר: זְכֻיּוֹת. אֲבָל לְפִי שֶׁדִּמָּה הֶעָוֹן לִבְגָדִים צוֹאִים, דִּמָּה הַזְּכֻיּוֹת לְמַחֲלָצוֹת בְּגָדִים נָאִים וּלְבָנִים:",2,0],[3,5,"וָאֹמַר. אֲנִי זְכַרְיָה:",1,0],[3,5,"יָשִׂימוּ צָנִיף טָהוֹר וְגוֹ׳. בִּקַּשְׁתִּי רַחֲמִים עָלָיו:",2,0],[3,6,"וַיָּעַד. לְשׁוֹן הַתְרָאָה, כְּמוֹ וְאָעִידָה בָם אֶת הַשָּׁמַיִם וְגוֹ׳ (דברים לא:כח):",1,0],[3,7,"אִם בִּדְרָכַי תֵּלֵךְ. וְגַם אֲנִי זֹאת אֶעֱשֶׂה לְךָ:",1,0],[3,7,"אַתָּה תָדִין אֶת בֵּיתִי. תִּשְׁפּוֹט וְתִהְיֶה פָּקִיד עַל בֵּית מִקְדָּשִׁי:",2,0],[3,7,"וְנָתַתִּי לְךָ מַהְלְכִים. כְּתַרְגּוּמוֹ: ״וּבַאֲחָיוּת מֵיתַיָּא אֲחַיֵּינָךְ וְאֶתֵּן לָךְ רַגְלִין דִּמְהַלְּכִין בֵּין שְׂרָפַיָּא הָאִלֵּין״. וּלְפִי פְשׁוּטוֹ: מְבַשְּׂרוֹ עַל בָּנָיו שֶׁיִּזְכּוּ לֶעָתִיד:",3,0],[3,7,"הָעוֹמְדִים. שְׂרָפִים וּמַלְאֲכֵי הַשָּׁרֵת שֶׁאֵין לָהֶם יְשִׁיבָה (שמות רבה כה):",4,0],[3,8,"אַתָּה וְרֵעֶיךָ. חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה הָיוּ (סנהדרין צג.):",1,0],[3,8,"אַנְשֵׁי מוֹפֵת. ״גֻּבְרִין כָּשְׁרִין לְמֵיעֲבַד לְהוֹן נִיסִּין״, שֶׁאַף לָהֶם נַעֲשָׂה נֵס (סנהדרין צג.)׃",2,0],[3,8,"כִּי הִנְנִי מֵבִיא אֶת עַבְדִּי צֶמַח. כִּי עַתָּה זְרֻבָּבֶל פַּחַת יְהוּדָה קָטָן בַּחֲצַר הַמֶּלֶךְ, אֲנִי מַצְמִיחַ לוֹ גְּדֻלָּה וְשֵׁם. נְתַתִּיו לְחֵן בְּעֵינֵי הַמֶּלֶךְ לְמַלֹּאות שְׁאֵלָתוֹ בְּבִנְיַן הַבַּיִת וְהָעִיר, כְּמוֹ שֶׁמְּפֹרָשׁ בְּעֶזְרָא דִּבְרֵי נְחֶמְיָה בֶּן חֲכַלְיָה, וְהוּא זְרֻבָּבֶל, כְּדַאֲמְרִינָן בְּסַנְהֶדְרִין (סנהדרין לח.):",3,0],[3,9,"כִּי הִנֵּה הָאֶבֶן. יְסוֹד הַבַּיִת אֲשֶׁר יְסַדְתֶּם בִּימֵי כּוֹרֶשׁ וּבָטְלוּ עַל יְדֵיכֶם, וְאוֹתוֹ הַיְּסוֹד וְעֹבִי הַחוֹמָה הָיָה מְעַט בְּעֵינֵיכֶם, כְּמוֹ שֶׁמְפֹרָשׁ בְּעֶזְרָא (עזרא ג:יב) וּבִנְבוּאַת חַגַּי (חגי ב:ג):",1,0],[3,9,"עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. סוֹפוֹ לְהַרְחִיב עַל אֶחָד שִׁבְעָה, וְכֵן תִּרְגֵּם יוֹנָתָן ״עַל אַבְנָא חֲדָא שִׁבְעָה עֵינִין חַזְיָן לָהּ״, וּלְשׁוֹן עֵינָיִם לְשׁוֹן מַרְאוֹת. וְלִי נִרְאֶה: שִׁבְעָה עֵינַיִם עַל שֵׁם עֵינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּעֵינָיו וּבְלִבּוֹ לְהוֹסִיף עָלָיו עַל אֶחָד שִׁבְעָה, לְפִי שֶׁדֻּגְמָתוֹ בִּנְבוּאָה זוֹ ״וְרָאוּ אֶת הָאֶבֶן הַבְּדִיל בְּיַד זְרֻבָּבֶל שִׁבְעָה אֵלֶּה עֵינֵי ה׳ הֵמָּה מְשׁוֹטְטִים וְגוֹ׳״ (זכריה ד:י). אֶלָּא לִמֵּד, שֶׁנָּתַן עֵינָיו לְהַרְבּוֹת כְּבוֹד הַבַּיִת בְּבִנְיָנוֹ:",2,0],[3,9,"הִנְנִי מְפַתֵּחַ פִּתֻּחָהּ. מַתִּיר קִשּׁוּרֶיהָ, מֵפִיר עֲצַת הָאוֹיְבִים אֲשֶׁר כָּתְבוּ שִׂטְנָה לְבַטֵּל הַמְּלָאכָה (עזרא ד:ו):",3,0],[3,9,"וּמַשְׁתִּי. וַהֲסִירוֹתִי:",4,0],[3,9,"בְּיוֹם אֶחָד. לֹא יָדַעְתִּי אֵיזֶה יוֹם. [תוספת: בְּיוֹם אֲשֶׁר הִתְחִילוּ לְהוֹסִיף עַל הַבִּנְיָן יָמִישׁ עֲוֺן הָאָרֶץ וְתִהְיֶה בְּרָכָה בְּפֵירוֹתָיו, כִּי עַכְשָׁיו מְאֵירָה כְּמוֹ שֶׁנֶּאֱמַר בִּנְבוּאַת חַגַּי (חגי ב:טז)]:",5,0],[4,2,"וְגֻלָּה עַל רֹאשָׁהּ. כְּמוֹ (יהושע טו:יט) גֻּלּוֹת עִלִּית, לְשׁוֹן מַעְיָן, כְּמִין סֵפֶל גָּדוֹל עָגוֹל:",1,0],[4,2,"וְשִׁבְעָה נֵרֹתֶיהָ. כְּמִין בָּזִיכִין שֶׁנּוֹתְנִין הַשֶּׁמֶן וְהַפְּתִילָה לְתוֹכָהּ:",2,0],[4,2,"שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. לְכָל נֵר וָנֵר בָּאִין שִׁבְעָה צִנּוֹרוֹת קְטַנִּים, שֶׁהַשֶּׁמֶן זָב מִן הַגֻּלָּה דֶּרֶךְ אוֹתָן מוּצָקוֹת לְכָל נֵר וָנֵר:",3,0],[4,3,"וּשְׁנַיִם זֵיתִים עָלֶיהָ. אֶצְלָהּ שְׁנֵי אִילָנוֹת שֶׁהַזֵּיתִים גְּדֵלִים בָּהֶם:",1,0],[4,3,"אֶחָד מִימִין הַגֻּלָּה וְאֶחָד מִשְּׂמֹאלָהּ וְגוֹ׳. וְכָאן לֹא פֵּרַשׁ עַל שְׁנֵי צַנְתְּרוֹת זָהָב הָאֲמוּרוֹת לְמַטָּה בַּפָּרָשָׁה, וְהֵם כְּמִין עֲרֵבוֹת וַעֲדָשִׁים שֶׁל בֵּית הַבַּד, שֶׁהֵם עוֹמְדִים אֵצֶל הַזֵּיתִים, וְהַזֵּיתִים נֶחְבָּטִים מֵאֲלֵיהֶם לְתוֹךְ הַצַּנְתְּרוֹת וּמִתְחַמְּמוֹת שָׁם כְּבַמַּעֲטָן וְנֶעֱצָרִים שָׁם בְּבֵית הַבַּד, וְהַשֶּׁמֶן נוֹפֵל לְתוֹךְ הַצַּנְתְּרוֹת וּמֵהַצַּנְתְּרוֹת לְתוֹךְ הַגֻּלָּה, וּמֵהַגֻּלָּה אֶל הַמּוּצָקוֹת, וּמֵהַמּוּצָקוֹת אֶל הַנֵּרוֹת. וְהַמּוּצָקוֹת וְהַנֵּרוֹת אַרְבָּעִים וְתֵשַׁע הָיוּ, רֶמֶז לָאוֹר שֶׁלֶּעָתִיד לָבֹא, אוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שֶׁל שִׁבְעַת יָמִים (ישעיה ל:כו), אַרְבָּעִים וְתֵשַׁע עַל אוֹר שֶׁל יוֹם בְּרֵאשִׁית:",2,0],[4,4,"מָה אֵלֶּה אֲדֹנִי. מַה זֶּה שֶׁהַזֵּיתִים נִמְסָקִים מֵאֲלֵיהֶם, וְהַשֶּׁמֶן בָּא אֶל הַנֵּרוֹת מֵאֵלָיו:",1,0],[4,6,"זֶה דְּבַר ה׳ אֶל זְרֻבָּבֶל. זֶה סִימָן לְךָ לְהַבְטִיחַ אֶת זְרֻבָּבֶל, כְּשֵׁם שֶׁהַזֵּיתִים וְהַשֶּׁמֶן הַזֶּה נִגְמָר מֵאֵלָיו לְכָל דְּבָרָיו, כָּךְ לֹא בְחַיִל וְלֹא בְכֹחַ שֶׁבָּכֶם תַּעֲשׂוּ אֶת בִּנְיַן בֵּיתִי:",1,0],[4,6,"כִּי אִם בְּרוּחִי. אֲנִי אֶתֵּן רוּחִי עַל דָּרְיָוֶשׁ וְיַנִּיחַ לָכֶם (ספרים אחרים: וִיצַוֶּה לָכֶם) לִבְנוֹת וְלַעֲשׂוֹת כָּל צָרְכֵי יְצִיאַת הַבִּנְיָן מִשֶּׁלּוֹ, וְלַעֲזֹר אֶתְכֶם בְּחִטִּין וְיַיִן וְשֶׁמֶן וְעֵצִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּעֶזְרָא (עזרא ו:ח-ט). וְלֹא תִצְטָרְכוּ לְעֶזְרַת אָדָם:",2,0],[4,7,"מִי אַתָּה הַר הַגָּדוֹל. שָׂרֵי עֵבֶר הַנָּהָר ״תַּתְּנַי פַּחַת עֵבֶר נַהֲרָה וּשְׁתַר בּוֹזְנַי וּכְנָוָתְהוֹן״ (עזרא ה:ג), שֶׁבִּטַּלְתֶּם הַמְּלָאכָה עַד כֹּה; מֵעַתָּה תִּהְיֶה לִפְנֵי זְרֻבָּבֶל לְמִישׁוֹר, אֵין לָכֶם שְׂרָרָה וּגְדֻלָּה עוֹד עָלָיו:",1,0],[4,7,"וְהוֹצִיא אֶת הָאֶבֶן הָרֹאשָׁה. הָאַדְרִיכָל יִקַּח אֶת אֶבֶן הַבְּדִיל בְּיָדוֹ (זכריה ד:י) לִהְיוֹת אַדְרִיכָל בְּרֹאשׁ הַבּוֹנִים, וְהֵם יִבְנוּ הַכֹּל כְּפִי דְּבָרָיו אֲשֶׁר יְצַוֶּה בְּבִנְיָן נָאֶה וּמְפֹאָר:",2,0],[4,7,"תְּשׁוּאוֹת חֵן חֵן. יִהְיֶה לָהּ לְאוֹתָהּ הָאֶבֶן שֶׁהַכֹּל יֹאמְרוּ מַה נָּאֶה בִּנְיָן זֶה הֶעָשׂוּי עַל יְדֵי אֶבֶן הַמִּשְׁקֹלֶת הַזֹּאת, תְּשׁוּאוֹת חֵן כְּמוֹ תְּשׁוּאוֹת נוֹי כְּמוֹ ״תְּשׁוּאוֹת מְלֵאָה עִיר הוֹמִיָּה״ (ישעיהו כב:ב), ״קוֹל שָׁאוֹן״ (ישעיהו סו:ו) כֻּלָּם לְשׁוֹן הַשְׁמָעַת קוֹל הֵם:",3,0],[4,9,"יְדֵי זְרֻבָּבֶל יִסְּדוּ הַבַּיִת הַזֶּה. מִתְּחִלָּה וְעַד סוֹף בִּימֵי כּוֹרֶשׁ הָרִאשׁוֹן (עזרא ג:י):",1,0],[4,9,"וִידָיו תְּבַצַּעְנָה. אוֹתוֹ עַתָּה, תְּבַצַּעְנָה לְשׁוֹן גְּמַר הוּא, כְּמוֹ ״כִּי יְבַצַּע ה׳ כָּל מַעֲשֵׂהוּ״ (ישעיה י:יב):",2,0],[4,10,"כִּי מִי בַז לְיוֹם. שֶׁיֻּסַּד הַבַּיִת אֲשֶׁר הֻקְטַן בְּעֵינֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (עזרא ג:יב) ״וְרַבִּים מֵהַכֹּהֲנִים אֲשֶׁר רָאוּ הַבַּיִת הָרִאשׁוֹן בְּיָסְדוֹ זֶה הַבַּיִת בְּעֵינֵיהֶם בֹּכִים בְּקוֹל גָּדוֹל״, וּבִנְבוּאַת חַגַּי (חגי ב:ג) ״הֲלֹא כְמוֹהוּ כְּאַיִן בְּעֵינֵיהֶם״. וְשָׂמְחוּ עַתָּה כְּשֶׁיִּרְאוּ אֶת הָאֶבֶן הַבְּדִיל הַתְּלוּיָה בְּחוּט הַמִּשְׁקֹלֶת בְּיַד אַדְרִיכַל רֹאשׁ הַבּוֹנִים, שֶׁמְּכַוֵּן בָּהּ רֹאשׁ הַפִּנָּה. וְזוֹ תִּהְיֶה בְּיַד זְרֻבָּבֶל.",1,0],[4,10,"שִׁבְעָה אֵלֶּה. עַל אֶחָד שִׁבְעָה בַּיְּסוֹד הָרִאשׁוֹן שֶׁבִּימֵי כּוֹרֶשׁ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״שִׁבְעָה נִדְבָּכִין כְּאִלֵּין״:",2,0],[4,10,"עֵינֵי ה׳ הֵמָּה מְשׁוֹטְטִים. וְלוֹ נִרְאֶה לַעֲשׂוֹת כֵּן, וְהוּא רָאָה אֶת זְרֻבָּבֶל זֶה הָגוּן לַדָּבָר:",3,0],[4,11,"מַה שְּׁנֵי הַזֵּיתִים. מָה רֶמֶז הֵם, וּמָה רֶמֶז שְׁנֵי שִׁבֲּלֵי זֵיתִים טְרוֹקָ״א בְּלַעַ״ז, קְבוּצוֹת זֵיתִים בְּעָנָף כְּעֵין שִׁבֹּלֶת:",1,0],[4,12,"אֲשֶׁר בְּיַד שְׁנֵי צַנְתְּרוֹת. כְּלוֹמַר: אֵצֶל שְׁנֵי הַצַּנְתְּרוֹת, כְּמוֹ ״רְאוּ חֶלְקַת יוֹאָב אֶל יָדִי״ (שמואל ב יד:ל):",1,0],[4,12,"הַמְּרִיקִים מֵעֲלֵיהֶם. אֶת הַשֶּׁמֶן הַזֶּה הַצָּלוּל וְטוֹב לְהָאִיר כְּזָהָב, כְּמוֹ (אִיּוֹב לז:כב) ״מִצָּפוֹן זָהָב יֶאֱתֶה״:",2,0],[4,14,"שְׁנֵי בְנֵי הַיִּצְהָר. קֶרֶן כְּהֻנָּה וּמַלְכוּת, הַנִּמְשָׁחִים בְּשֶׁמֶן הַמִּשְׁחָה:",1,0],[4,14,"הָעוֹמְדִים עַל אֲדוֹן כָּל הָאָרֶץ. לְבַקֵּשׁ מִלְּפָנָיו לְהַחֲזִיר אֶת גְּדֻלָּתָם:",2,0],[4,14,"שְׁנֵי בְנֵי הַיִּצְהָר. יֵצֶר טוֹב וְיֵצֶר הָרָע מִתְהַפֵּךְ לְטוֹב בִּזְכוּת הַתּוֹרָה:",3,0],[5,1,"מְגִלָּה עָפָה. רַבּוֹתֵינוּ פֵּרְשׁוּ כְּפוּלָה וְאָמְרוּ שֶׁהַתּוֹרָה כְּתוּבָה בָּהּ וְלָמְדוּ מִכָּאן שֶׁהָעוֹלָם אֶחָד מִשְּׁלֹשֶׁת אֲלָפִים וּמָאתַיִם בַּתּוֹרָה כִּדְאִיתָא בְּעֵירוּבִין (עירובין כא.) וְיוֹנָתָן תִּרְגֵּם ״מְגִלְּתָא פָּרְחָא פּוֹרַחַת בָּאֲוִיר״, וּלְפִי פְשׁוּטוֹ שֶׁל פָּרָשָׁה מְגִלַּת פֻּרְעָנוּת הָיְתָה וְהוּא שֶׁרָאָה (יחזקאל ב:י) ״וְכָתוּב אֵלֶיהָ קִינִים וָהֶגֶה וָהִי״:",1,0],[5,3,"זֹאת הָאָלָה. זֹאת שֶׁכָּתוּב בָּהּ פֻּרְעָנוּת נִקְמַת שְׁבוּעוֹת שֶׁקֶר:",1,0],[5,3,"הַיּוֹצֵאת. עַתָּה מִבֵּית קָדְשֵׁי הַקֳּדָשִׁים מִלִּפְנֵי הַשְּׁכִינָה לְהִתְהַלֵּךְ עַל פְּנֵי כָל הָאָרֶץ וְזֶהוּ אָרְכָּהּ עֶשְׂרִים וְרָחְבָּהּ עֶשֶׂר (זכריה ה:ב) כְּמִדַּת פֶּתַח הָעֲזָרָה וְהַהֵיכָל (מלכים א ו:ג) אֲשֶׁר יָצְאָת דֶּרֶךְ שָׁם:",2,0],[5,3,"כִּי כָל הַגֹּנֵב. עַד עַכְשָׁיו:",3,0],[5,3,"מִזֶּה כָּמוֹהָ נִקָּה. מִזֶּה הַפֻּרְעָנוּת כְּמוֹ שֶׁהוּא מְפֹרָשׁ בָּהּ נִקָּה וְלֹא נִשְׁתַּלֵּם פֻּרְעָנוּת יְחִידִים הָעוֹבְרִים עַל הַתּוֹרָה, אֶלָּא הִמְתִּין עַד שֶׁנִּתְמַלֵּאת סְאַת כֻּלָּם, וְלָקוּ כֻּלָּם כְּאֶחָד בַּחֻרְבָּן וּבַגּוֹלָה. וְכֵן כָּל הַנִּשְׁבָּע לַשֶּׁקֶר עַד הֵנָּה מִזֶּה הַפֻּרְעָנוּת, כְּמוֹ שֶׁהַמְּגִלָּה הַזֹּאת מַגֶּדֶת: נִקָּה וְלֹא נִשְׁתַּלֵּם. אֲבָל מִכָּאן וָאֵילָךְ הוֹצֵאתִיהָ לָשׁוּט בָּאָרֶץ וְלִנְקֹם מִן הַגַּנָּבִים וְהַנִּשְׁבָּעִים לַשֶּׁקֶר מֵעַכְשָׁיו, וּבָא אֶל בֵּית הַגַּנָּב וְגוֹ׳:",4,0],[5,5,"שָׂא נָא עֵינֶיךָ וּרְאֵה. עוֹד יוֹצֵאת אַחֶרֶת שֶׁתֵּצֵא מִבֵּית קֹדֶשׁ הַקֳּדָשִׁים:",1,0],[5,6,"וָאֹמַר מַה הִיא. הַיּוֹצֵאת שֶׁתֹּאמַר אֵלַי לִרְאוֹת:",1,0],[5,6,"וַיֹּאמֶר זֹאת הָאֵיפָה. שֶׁתֵּרָאֶה יוֹצֵאת כְּמִין אֵיפָה שֶׁמּוֹדְדִין בָּהּ:",2,0],[5,6,"וַיֹּאמֶר זֹאת עֵינָם בְּכָל הָאָרֶץ. וּלְאַחַר שֶׁרְאִיתִיהָ אָמַר: זֹאת הִיא מִדָּה שֶׁלָּקוּ בָּהּ אוֹתָם שֶׁעֵינֵיהֶם בְּכָל הָאָרֶץ לִגְזֹל וְלַעֲשֹׁק, ״לְהַקְטִין אֵיפָה וּלְהַגְדִּיל שֶׁקֶל״ (עמוס ח:ה), וְנִמְדַּד לָהֶם סְאָה בִּסְאָה:",3,0],[5,7,"וְהִנֵּה כִּכַּר עוֹפֶרֶת נִשֵּׂאת. רָאִיתִי שֶׁנִּשֵּׂאת מֵעַל הָאָרֶץ לָאֲוִיר מִשְׁקַל כִּכַּר עוֹפֶרֶ,ת וְרָאִיתִי עוֹד זֹאת אִשָּׁה אַחַת יוֹשֶׁבֶת בְּתוֹךְ הָאֵיפָה:",1,0],[5,8,"וַיֹּאמֶר זֹאת הָרִשְׁעָה. הָאִשָּׁה זֹאת שֶׁאַתָּה רוֹאֶה בְּתוֹךְ הָאֵיפָ,ה הִיא מִדַּת דֶּרֶךְ הָרִשְׁעָה אֲשֶׁר יִנְהֲגוּ בָּהּ הָרְשָׁעִים, וְהִנֵּה עַתָּה נְתוּנִים בְּתוֹכָהּ לִלְקוֹת בְּתוֹךְ הַסְּאָה עַצְמָהּ שֶׁמָּדְדוּ בָּהּ, מִדָּה בְּמִדָּה:",1,0],[5,8,"וַיַּשְׁלֵךְ אֹתָהּ. עַד עַתָּה הָיְתָה יוֹשֶׁבֶת, וְהוּא הִשְׁלִיכָהּ וְחָבְטָהּ לְתוֹכָהּ, רֶמֶז לְיִסּוּרִים וְלָעֳנָשִׁים:",2,0],[5,8,"וַיַּשְׁלֵךְ אֶת אֶבֶן הָעוֹפֶרֶת אֶל פִּיהָ. לְשַׁקְּעָהּ, לְמַעַן לֹא יִגְדְּלוּ עוֹד, וְלֹא יִשָּׁמַע קוֹלָן לְשַׁדֵּד עֲנִיִּים וְאֶבְיוֹנִים:",3,0],[5,9,"שְׁתַּיִם נָשִׁים יוֹצְאוֹת. מִן הַבַּיִת:",1,0],[5,9,"הַחֲסִידָה. דַּיָּה לְבָנָה וולטויא״ר בְּלַעַ״ז (חולין סג.)׃",2,0],[5,11,"וְהוּכַן וְהֻנִּיחָה שָׁם. וְהוּכַן הַבַּיִת וְהֻנְּחָה הָאֵיפָה עִם הָרְשָׁעִים שֶׁבְּתוֹכָהּ:",1,0],[5,11,"שָׁם. בְּאוֹתוֹ הַבַּיִת:",2,0],[5,11,"עַל מְכוּנָתָהּ. עַל קְבִיעוּתָהּ וְעַל בְּסִיסָהּ. כָּאן רָמַז לוֹ, שֶׁבַּעֲוֹנָם שֶׁל יִשְׂרָאֵל שֶׁמָּדְדוּ בִּסְאַת עֲבֵרוֹת וָרֶשַׁע, לָקוּ בְּאוֹתָהּ מִדָּה. וּבָאוּ שְׁתֵּי אֻמּוֹת שֶׁמָּלְכוּ כְּאַחַת, הֵם בָּבֶל וְכַשְׂדִים, חֵיל נְבוּכַדְנֶצַּר, וְהִגְלוּם לְבָבֶל; וְשָׁם עָמְדוּ קְבוּעִים עַל מְכוֹן בָּסִיס הַהֻקְבַּע לָהֶם, וְהוּא לְפִי מְלֹאות שִׁבְעִים שָׁנָה עַד עַתָּה (ירמיה כט:י), שֶׁחָזְרוּ. וְנוֹטֶה פֵּרוּשׁ זֶה אַחַר יוֹנָתָן בְּמִקְצָת. וְכַמָּה דְּרָכִים פּוֹתְרִים בָּהּ, וְלֹא נִתְיַשְּׁבוּ לִי. וְרַבּוֹתֵינוּ פֵּרְשׁוּ וְלָמְדוּ מִכָּאן, שֶׁנִּמְסַר לָהֶם יֵצֶר הָרַע לְאַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, וְשַׁדְיוּהּ לְדוּדָא דְּאַבְרָא וְחַפְיוּהוּ בְּאַבְרָא מִשּׁוּם דְּשָׁאִיב קָלֵיהּ, כִּדְאִיתָא בְּסַנְהֶדְרִין (סנהדרין סד.) וּבְמַסֶּכֶת יוֹמָא (יומא סט:). וְשֶׁפָּתַרְתִּי מַלְכוּת נְבוּכַדְנֶצַּר בְּכֶפֶל שְׁתֵּי אֻמּוֹת – רָאִיתִי בְּמִדְרַשׁ תִּילִּים, שֶׁאַרְבַּע מַלְכֻיּוֹת הַלָּלוּ שֶׁשִּׁעְבְּדוּ בְּיִשְׂרָאֵל, כְּפוּלוֹת הָיוּ: בָּבֶל וְכַשְׂדִים, מָדַי וּפָרַס, אַנְטִיוֹכוּס וּמוֹקְדוֹן, אֱדוֹם וְיִשְׁמָעֵאל. וְעַל כָּכָה יִסֵּד הַקָּלִירִי: רְבִיעִית הִיא שְׁמִינִית, עַל אֱדוֹם:",3,0],[6,1,"וְהֶהָרִים הָרֵי נְחֹשֶׁת. סִימָן עַל חֹזֶק מַלְכֻיּוֹת הַלָּלוּ הַבָּא לָהֶם מִבֵּין שְׁנֵי הֶהָרִים שֶׁהוּא קָשֶׁה וְאַמִּיץ, שֶׁאֵלּוּ אַרְבַּע מַרְכָּבוֹת שְׁלוּחֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת מֶמְשֶׁלֶת לְאַרְבַּע מַלְכֻיּוֹת: בָּבֶל וּמָדַי יָוָן וֶאֱדוֹם:",1,0],[6,2,"סוּסִים אֲדֻמִּים. הֵם שֶׁהִרְכִּיבוּ אֶת בָּבֶל, שֶׁהִיא אֲדֻמָּה, כְּמוֹ שֶׁכָּתוּב ״אַנְתְּ הוּא רֵאשָׁה דִּי דַהֲבָא״ (דניאל ב:לח):",1,0],[6,2,"שְׁחוֹרִים. לְהַרְכִּיב אֶת מָדַי שֶׁהִשְׁחִירָה אֶת פְּנֵיהֶם שֶׁל יִשְׂרָאֵל בִּימֵי הָמָן (מגילה יא.):",2,0],[6,3,"לְבָנִים. לְהַרְכִּיב אֶת פָּרַס שֶׁבָּנָה אֶת הַבַּיִת (אבות דרבי נתן נוסחא ב כה,ב):",1,0],[6,3,"בְּרֻדִּים. הֵמָּה מְנֻמָּרִים, לְהַרְכִּיב אֶת יָוָן, שֶׁעִנּוּ אֶת יִשְׂרָאֵל בְּמִינֵי גְּזֵרוֹת מְשֻׁנּוֹת זוֹ מִזֶּה (ויקרא רבה יג:ה):",2,0],[6,3,"אֲמֻצִּים. לְהַרְכִּיב יִשְׁמָעֵאל (ספרים אחרים: אֱדוֹם) וְלֹא יָדַעְתִּי מַהוּ לְשׁוֹן אֲמֻצִּים, וְיוֹנָתָן תִּרְגֵּם ״קִטְמָנִין״:",3,0],[6,5,"אֵלֶּה אַרְבַּע רוּחוֹת הַשָּׁמַיִם. שָׂרֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מַלְכֻיּוֹת הַקַּדְמוֹנִיּוֹת הַמּוֹשְׁלוֹת בְּאַרְבַּע רוּחוֹת הַשָּׁמַיִם:",1,0],[6,5,"יוֹצְאוֹת מֵהִתְיַצֵּב וְגוֹ׳. בָּאוּ לְפָנָיו וְנָתַן לָהֶם רְשׁוּת מִפִּיו לִמְשֹׁל:",2,0],[6,6,"אֲשֶׁר בָּהּ הַסּוּסִים הַשְּׁחֹרִים יוֹצְאִים אֶל אֶרֶץ צָפוֹן. לְהַרְכִּיב אֶת מָדַי. וְעַל הָאֲדוּמִים לֹא כָּתַב יוֹצְאִים, שֶׁכְּבָר כָּלְתָה לָהּ מֶמְשֶׁלֶת בָּבֶל:",1,0],[6,6,"וְהַלְּבָנִים יָצְאוּ אֶל אַחֲרֵיהֶם. לְהַרְכִּיב אֶת פָּרַס, שֶׁשְּׁתֵּיהֶן בַּצָּפוֹן, וּמָשְׁלוּ עַל בָּבֶל:",2,0],[6,6,"וְהַבְּרֻדִּים יָצְאוּ אֶל אֶרֶץ הַתֵּימָן. לְהַרְכִּיב אֶת יָוָן וְיִטְּלוּ הַמְּלוּכָה מִיַּד פָּרַס. וּבְפִתְרוֹנוֹ לְרַב סְעַדְיָה בְּדָנִיֵּאל רָאִיתִי מֶלֶךְ הַנֶּגֶב הוּא מֶלֶךְ יָוָן (דניאל יא:ה):",3,0],[6,7,"וְהָאֲמֻצִּים יָצְאוּ וַיְבַקְשׁוּ. מִלְּפָנָיו שֶׁיְּהֵא אֹרֶךְ גָּדוֹל לְמֶמְשַׁלְתָּם, לָלֶכֶת בְּכָל הָאָרֶץ:",1,0],[6,7,"וַיֹּאמֶר לְכוּ הִתְהַלְּכוּ בָאָרֶץ. נָתַן לָהֶם רְשׁוּת לִמְשֹׁל מִמְשָׁל רַב (דניאל יא:ג), וְהוּא מַלְכוּת אֱדוֹם:",2,0],[6,8,"רְאֵה הַיּוֹצְאִים אֶל אֶרֶץ צָפוֹן. לְהַרְכִּיב מָדַי וּפָרָס:",1,0],[6,8,"הֵנִיחוּ אֶת רוּחִי. שִׁכְּכוּ אֶת חֲמָתִי בְּבָבֶל, שֶׁהִשְׁחִיתוּ אֶת בֵּלְשַׁצַּר וְזַרְעוֹ שֶׁל נְבוּכַדְנֶצַּר (דניאל ה:ל). הוּא שֶׁאָמַר (ישעיהו מח:יד) ״ה׳ אֲהֵבוֹ יַעֲשֶׂה חֶפְצוֹ בְּבָבֶל וְגוֹ׳״:",2,0],[6,10,"לָקוֹחַ מֵאֵת הַגּוֹלָה מֵחֶלְדַּי וְגוֹ׳, אֲשֶׁר בָּאוּ מִבָּבֶל. כָּל הָאֲנָשִׁים הָאֵלֶּה:",1,0],[6,12,"צֶמַח שְׁמוֹ. הוּא זְרֻבָּבֶל הָאָמוּר לְמַעְלָה ״הִנְנִי מֵבִיא אֶת עַבְדִּי צֶמַח״ (זכריה ג:ח), וְעַל שֵׁם שֶׁצָּמְחָה גְּדֻלָּתוֹ מְעַט מְעַט. וְיֵשׁ פּוֹתְרִים אוֹתוֹ (תנחומא קרח יב) בְּמֶלֶךְ הַמָּשִׁיחַ, אֲבָל כָּל הָעִנְיָן הַזֶּה מְדַבֵּר בְּבַיִת שֵׁנִי:",1,0],[6,12,"וּמִתַּחְתָּיו יִצְמָח. מִזֶּרַע הַמְּלוּכָה:",2,0],[6,13,"וְהוּא יִשָּׂא הוֹד. הוֹד נְשִׂיאוּת:",1,0],[6,13,"וְיָשַׁב. כֹּהֵן גָּדוֹל עַל כִּסֵּא הַכְּהֻנָּה:",2,0],[6,13,"וַעֲצַת שָׁלוֹם וְגוֹ׳. הַנָּשִׂיא וְהַכֹּהֵן יֹאהֲבוּ זֶה אֶת זֶה:",3,0],[6,14,"וְהָעֲטָרוֹת תִּהְיֶה לְחֵלֶם וְגוֹ׳. מִקְרָא מְסֹרָס הוּא, וְהָעֲטָרוֹת תִּהְיֶינָה בְּהֵיכַל ה׳ לְזִכָּרוֹן טוֹב לְחֵלֶם וּלְטוֹבִיָּה אֲשֶׁר הִתְנַדְּבוּ הַכֶּסֶף וְהַזָּהָב. וְאוֹתָן עֲטָרוֹת הָיוּ תְּלוּיוֹת בַּחֲלוֹנוֹת בְּגֹבַהּ הַהֵיכָל, כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת מִדּוֹת (מידות ג,ח):",1,0],[6,14,"חֵלֶם. הוּא חֶלְדָּי (זכריה ו:י):",2,0],[6,15,"וְהָיָה אִם שָׁמוֹעַ. וְהָיָה לָכֶם הַדָּבָר הַזֶּה אִם שָׁמוֹעַ תִּשְׁמְעוּ וְגוֹ׳:",1,0],[7,2,"וַיִּשְׁלַח בֵּית אֵל שַׂרְאֶצֶר וְרֶגֶם מֶלֶךְ וַאֲנָשָׁיו. אֲנָשִׁים צַדִּיקִים הָיוּ, וְשָׁלְחוּ מִבָּבֶל לִקְרוֹבֵיהֶם שֶׁבְּבֵית אֵל לָבֹא לְחַלּוֹת אֶת פְּנֵי ה׳ בִּירוּשָׁלַיִם בַּעֲדָם, וְלִשְׁאֹל מֵאֵת הַכֹּהֲנִים לְהוֹדִיעָם אִם יִבְכּוּ בְּחֹדֶשׁ אָב, אַחֲרֵי אֲשֶׁר חָזַר הַבַּיִת לְהִבָּנוֹת:",1,0],[7,3,"הַנָּזֵר. לִפְרוֹשׁ מִן הַתַּעֲנוּג כַּאֲשֶׁר עָשִׂיתִי זֶה שִׁבְעִים שָׁנָה. אֵין נְזִירָה בְּכָל מָקוֹם אֶלָּא פְּרִישׁוּת (ספרא אמור פרשה ד, א):",1,0],[7,5,"וּבַשְּׁבִיעִי. הוּא צוֹם גְּדַלְיָה (ראש השנה יח:):",1,0],[7,5,"הֲצוֹם צַמְתֻּנִי אָנִי. הֵ״א נְקוּדָה חֲטַף פַּתָּח, לְפִי שֶׁהִיא מְשַׁמֶּשֶׁת לְשׁוֹן תְּמִיהָא: שֶׁמָּא לִכְבוֹדִי צַמְתֶּם, שֶׁתִּהְיוּ צְרִיכִים לָצוּם גַּם עַתָּה?:",2,0],[7,6,"וְכִי תֹאכְלוּ וְכִי תִשְׁתּוּ. וְאִם לֹא תָצוּמוּ, מַה לִּי גַּם בָּזוֹ? הֲלֹא אַתֶּם לַהֲנָאַתְכֶם הוּא הַמַּאֲכָל וְהַמִּשְׁתֶּה:",1,0],[7,7,"הֲלֹא אֶת הַדְּבָרִים. מִי גָּרַם לָכֶם הַצּוֹם וְהַמִּסְפֵּד? הֲלֹא דִבְרֵי תוֹכָחוֹת אֲשֶׁר קָרָא ה׳ וְגוֹ׳, הֵם הֶחֱרִיבוּ אֶתְכֶם, וְעַל כֵּן צַמְתֶּם. וְאֵלֶּה הַדְּבָרִים אֲשֶׁר קָרָא: ״מִשְׁפַּט אֱמֶת שְׁפֹטוּ״ (זכריה ז:ט):",1,0],[7,12,"שָׂמוּ שָׁמִיר. תּוֹלַעַת חָזָק מִצּוּר, מַרְאִין אוֹתוֹ עַל הָאֶבֶן וְהִיא מִתְבַּקַּעַת (סוטה מח:):",1,0],[7,13,"וַיְהִי כַּאֲשֶׁר קָרָא וְלֹא שָׁמֵעוּ. אָמַר ה׳ צְבָאוֹת עֲלֵיהֶן בְּאוֹתָן הַיָּמִים כֵּן יִקְרְאוּ וְלֹא אֶשְׁמָע:",1,0],[7,14,"וָאֵסָעֲרֵם. בַּגָּלוּת, וְכֵן עָשִׂיתִי:",1,0],[7,14,"וַיָּשִׂימוּ. בַּעֲוֹנָם:",2,0],[7,14,"אֶרֶץ חֶמְדָּה לְשַׁמָּה. וְהוּא גָּרַם לָהֶם הַצּוֹם וְהַמִּסְפֵּד, אֲבָל עַתָּה: ״קִנֵּאתִי לְצִיּוֹן״ (זכריה ח:ב) – בִּשְׁבִיל צִיּוֹן אֲקַנֵּא אֶת הַכַּשְׂדִּים:",3,0],[8,2,"קִנֵּאתִי לָהּ. בִּשְׁבִילָהּ, וְלֹא תִזָּקְקוּ לָצוּם וְלִסְפֹּד. וְכֵן סוֹף הָעִנְיָן ״צוֹם הַחֲמִישִׁי וְגוֹמֵר״ (זכריה ח:יט):",1,0],[8,4,"מֵרֹב יָמִים. יִהְיוּ צְרִיכִים לְמִשְׁעֶנֶת בְּיָדָם:",1,0],[8,6,"כִּי יִפָּלֵא. בְּעֵינֵיהֶם הַחֶסֶד הַגָּדוֹל אֲשֶׁר אֶעֱשֶׂה לָהֶם:",1,0],[8,6,"גַּם בְּעֵינַי יִפָּלֵא. אֵיךְ שַׁבְתִּי מִן הֶחָרוֹן הַגָּדוֹל. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל שְׁחִיטַת יֵצֶר הָרָע בְּמַסֶּכֶת סֻכָּה (סוכה נב.): בְּעֵינַי יִפָּלֵא אֵיךְ יוּכְלוּ הַצַּדִּיקִים לַעֲמֹד כְּנֶגְדּוֹ בְּחַיֵּיהֶם:",2,0],[8,9,"תֶּחֱזַקְנָה יְדֵיכֶם. לִבְנוֹת וּלְהַשְׁלִים, וְאַל תִּירְאוּ מֵעַם הָאָרֶץ הַמְרַפִּים יְדֵיכֶם וּמְבַהִילִים אֶתְכֶם מִלִּבְנוֹת, וּכְמוֹ שֶׁמְּפֹרָשׁ בְּסֵפֶר עֶזְרָא (עזרא ד:ד):",1,0],[8,9,"הַשּׁוֹמְעִים בַּיָּמִים הָאֵלֶּה. בִּשְׁנַת אַרְבַּע לְדָרְיָוֶשׁ:",2,0],[8,9,"אֵת הַדְּבָרִים הָאֵלֶּה. שֶׁל נִחוּמִים מִפִּי הַנְּבִיאִים אֲשֶׁר נִבְּאוּ לָהֶם אָז בְּיוֹם יֻסַּד בֵּית ה׳ בִּשְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ (חגי א:טו) אֶת הַדְּבָרִים לְהַתְחִיל בַּמְּלָאכָה. כִּי נִבְחֲנוּ אוֹתָם הַנְּבִיאִים בְּעֵינֵיהֶם בְּדִבְרֵיהֶם, שֶׁהֵם נְבִיאֵי אֱמֶת, וּלְפִיכָךְ כְּדַאי הֵם לִסְמֹךְ עֲלֵיהֶם אַף בְּדִבְרֵי נִחוּמִים שֶׁל עַכְשָׁיו. וּבַמֶּה נִבְחֲנוּהָ? כִּי לִפְנֵי הַיָּמִים הָהֵם שְׂכַר הָאָדָם וְגוֹמֵר. וְהֵם נִבְּאוּ לָכֶם שֶׁמִּשֶּׁתַּתְחִילוּ בַּמְּלָאכָה תָּבֹא בְּרָכָה בְּמַעֲשֵׂה יְדֵיכֶם, וְנִתְקַיְּמוּ דִּבְרֵיהֶם, שֶׁהֲרֵי עַתָּה לֹא כַיָּמִים הָרִאשֹׁנִים:",3,0],[8,14,"וְלֹא נִחָמְתִּי. עַל אֲשֶׁר זַמֹּתִי לְהָבִיא עֲלֵיכֶם לַחֲזוֹר בִּי, אֶלָּא הֲבִיאוֹתִיהָ. כֵּן לֹא אֶתְנַחֵם עַל הַטּוֹבָה אֲשֶׁר זָמַמְתִּי לָכֶם:",1,0],[8,16,"וּמִשְׁפַּט שָׁלוֹם. הִיא הַפְּשָׁרָה:",1,0],[8,17,"וְאִישׁ אֶת רָעַת רֵעֵהוּ. הִזְהִירָם עַל שִׂנְאַת חִנָּם, וְהִיא שֶׁהֶחֱרִיבָה בֵּית הַמִּקְדָּשׁ שֵׁנִי (יומא ט:):",1,0],[8,19,"צוֹם הָרְבִיעִי. צוֹם שֶׁל תַּמּוּז, שֶׁהוּא רְבִיעִי לֶחֳדָשִׁים:",1,0],[8,19,"צוֹם הַחֲמִישִׁי. שֶׁל אָב:",2,0],[8,19,"וְצוֹם הַשְּׁבִיעִי. שְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁבּוֹ נֶהֱרַג גְּדַלְיָה (מלכים ב כה:כה; ירמיהו מא:א-ב):",3,0],[8,19,"וְצוֹם הָעֲשִׂירִי. שֶׁל טֵבֵת (ראש השנה יח:):",4,0],[8,23,"עֲשָׂרָה אֲנָשִׁים. מִשִּׁבְעִים לָשׁוֹן, הֲרֵי שְׁבַע מֵאוֹת לְכָל כָּנָף וְכָנָף. הֲרֵי לְאַרְבַּע כַּנְפֵי הַטַּלִּית אַלְפַּיִם וּשְׁמוֹנֶה מֵאוֹת (שבת לב:):",1,0],[9,1,"בְּאֶרֶץ חַדְרָךְ. דָּרַשׁ רַבִּי יְהוּדָה בַּר אֶלְעָאִי: זֶה מָשִׁיחַ, שֶׁהוּא חַד לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת וְרַךְ לְיִשְׂרָאֵל. אָמַר לוֹ רַבִּי יוֹסֵי בֶּן דּוֹרְמַסְקִית: יְהוּדָה בְּרִבִּי, עַד מָתַי אַתָּה מְעַוֵּת עָלֵינוּ אֶת הַכְּתוּבִים? מֵעִיד אֲנִי עָלַי שָׁמַיִם וָאָרֶץ, שֶׁאֲנִי מִדַּמֶּשֶׂק, וְיֵשׁ מָקוֹם שֶׁשְּׁמוֹ חַדְרָךְ. וּמָה אֲנִי מְקַיֵּם וְדַמֶּשֶׂק מְנֻחָתוֹ? שֶׁעֲתִידָה יְרוּשָׁלַיִם לִהְיוֹת מַגַּעַת עַד דַּמֶּשֶׂק, וְאֵין מְנוּחָתוֹ אֶלָּא יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר ״זֹאת מְנוּחָתִי עֲדֵי עַד״ (תהלים קלב:יד). אָמַר לוֹ: וּמָה אֲנִי מְקַיֵּם ״וְנִבְנְתָה עִיר עַל תִּלָּהּ״ (ירמיהו ל:יח)? אָמַר לוֹ: שֶׁאֵין עֲתִידָה לָזוּז מִמְּקוֹמָהּ. כָּךְ בְּרַיְתָא שְׁנוּיָה בְּסִפְרֵי (ספרי דברים א:א):",1,0],[9,1,"כִּי לַה׳ עֵין אָדָם. כִּי בַּיּוֹם הַהוּא יִשְׁעֶה הָאָדָם עַל עוֹשֵׂהוּ וְעֵינָיו אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא תִּרְאֶינָה (ישעיהו יז:ז), כְּמוֹ שֶׁאָמַר לְמַעְלָה ״נֵלְכָה עִמָּכֶם״ (זכריה ח:כג), וְנִסְפְּחוּ הֵם וְעָרֵיהֶם עַל עָרֵי יִשְׂרָאֵל:",2,0],[9,1,"וְכָל שִׁבְטֵי יִשְׂרָאֵל. חֲשׁוּבִים לַה׳ עַל כָּל הָאֻמּוֹת הַקַּדְמוֹנִים. כְּיוֹצֵא בוֹ: ״וְשָׁלֹמֹה אָהַב נָשִׁים נָכְרִיּוֹת רַבּוֹת וְאֶת בַּת פַּרְעֹה״ (מלכים א יא:א), וַהֲלֹא בַּת פַּרְעֹה בִּכְלָל הָיְתָה? אֶלָּא שֶׁהָיְתָה בַּת פַּרְעֹה חֲבִיבָה לוֹ כְּנֶגֶד כֻּלָּם. אַף כָּאן, כָּל הָאֻמּוֹת יִהְיוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְיִשְׂרָאֵל כְּנֶגֶד כּוּלָם:",3,0],[9,2,"וְגַם חֲמָת תִּגְבָּל בָּהּ. תַּשִּׂיג גְּבוּלָהּ בִּגְבוּל יְרוּשָׁלָיִם:",1,0],[9,2,"צוֹר וְצִידוֹן. גַּם הֵמָּה בְּנוֹתֶיהָ, אַף עַל פִּי שֶׁחָכְמָה מְאֹד שֶׁנִּתְחַכְּמָה מְאֹד, וּסְבוּרָה לִהְיוֹת לְעוֹלָם גְּבֶרֶת בְּחָכְמָתָהּ:",2,0],[9,3,"וַתִּבֶן צוֹר מָצוֹר לָהּ. וְאוֹמֶרֶת: ״מִי יוֹרִידֵנִי לָאָרֶץ״? (עובדיה א:ג):",1,0],[9,3,"וַתִּצְבׇּר כֶּסֶף כֶּעָפָר. וּמִתְהַלֶּלֶת בְּעָשְׁרָהּ׃",2,0],[9,3,"וְחָרוּץ. מִין מַרְאִית זָהָב׃",3,0],[9,4,"הִנֵּה אֲדֹ׳. שֶׁהוּא שַׁלִּיט עַל כֹּל׃",1,0],[9,4,"יוֹרִישֶׁנָּה. לְשׁוֹן ״מוֹרִישׁ וּמַעֲשִׁיר״ (שמואל א ב:ז):",2,0],[9,4,"וְהִכָּה בַיָּם חֵילָהּ. וְהִבְלִיעַ בְּתוֹךְ יַמִּים מָמוֹנָהּ, יַעֲלֶה עָלֶיהָ אֶת הַיָּם וְיַטְבִּיעֶנָּה, כְּמוֹ שֶׁאָמַר יְחֶזְקֵאל (יחזקאל כז:כו-כז):",3,0],[9,5,"תִּרְאֶה אַשְׁקְלוֹן. אֶת מַפֶּלֶת צוֹר וְתִירָא:",1,0],[9,5,"וְעֶקְרוֹן אַף הִיא תִּירָא:",2,0],[9,5,"כִּי הוֹבִישׁ מֶבָּטָהּ. שֶׁהָיְתָה נִשְׁעֶנֶת עַל צוֹר, שֶׁהָיְתָה רֹאשׁ לִבְנֵי עֵשָׂו. וְעֶקְרוֹן אַף הִיא לֶאֱדוֹם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת מְגִלָּה (מגילה ו.). וּתְחִלָּה הָיְתָה מִשֶּׁל פְּלִשְׁתִּים:",3,0],[9,6,"וְיָשַׁב מַמְזֵר בְּאַשְׁדּוֹד. וְיָשַׁב עַם נָכְרִי בְּאַשְׁדּוֹד, הֵם יִשְׂרָאֵל שֶׁהָיוּ בָּהּ נָכְרִים (קידושין עב:):",1,0],[9,7,"וַהֲסִרֹתִי דָמָיו מִפִּיו. שֶׁל עֵשָׂו אֵלּוּ בֵּית בִּימָה שֶׁלָּהֶם שֶׁהָיוּ זוֹרְקִים שָׁם דְּמֵי זִבְחֵיהֶם (מגילה ו.). וְיֵשׁ פּוֹתְרִין שְׁפִיכוּת דָּמִים שֶׁהָיָה שׁוֹפֵךְ דְּמֵי יִשְׂרָאֵל:",1,0],[9,7,"וְנִשְׁאַר גַּם הוּא לֵאלֹהֵינוּ. אֵלּוּ בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת שֶׁבַּגָּלוּת (מגילה כט.):",2,0],[9,7,"וְהָיָה כְּאַלּוּף בִּיהוּדָה. אֵלּוּ טַרְטִיָּאוֹת וְקַרְקְסִיָּאוֹת שֶׁלָּהֶם, שֶׁעֲתִידִים שָׂרֵי יְהוּדָה לְלַמֵּד בָּהֶם תּוֹרָה בָּרַבִּים:",3,0],[9,7,"וְהָיָה כְּאַלּוּף. לְשׁוֹן אִלּוּף וְלִמּוּד:",4,0],[9,7,"וְעֶקְרוֹן. תִּהְיֶה לְיִשְׂרָאֵל:",5,0],[9,7,"כִּיבוּסִי. יְרוּשָׁלַיִם:",6,0],[9,8,"וְחָנִיתִי לְבֵיתִי מִצָּבָה. אֶחֱנֶה אֵצֶל בֵּיתִי לְהָגֵן עָלֶיהָ מִן הַמַּעֲמִידִים מִבְצָר וּמַשְׁחִית, שֶׁלֹּא יַצִּיבוּ עָלֶיהָ. וְדֻגְמָתוֹ ״וְכָל צֹבֶיהָ וּמְצֹדָתָהּ״ (ישעיהו כט:ז). וְיֵשׁ עוֹד לִפְתֹּר מִצָּבָה כְּמוֹ מִצָּבָא בְּאָלֶ״ף:",1,0],[9,8,"כִּי עַתָּה רָאִיתִי. צָרָתָם בְּעֵינַי, אַף עַל פִּי שֶׁעַד הֵנָּה הִסְתַּרְתִּי פָנַי מֵהֶם:",2,0],[9,9,"הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ. אִי אֶפְשָׁר לְפוֹתְרוֹ אֶלָּא עַל מֶלֶךְ הַמָּשִׁיחַ שֶׁנֶּאֱמַר בּוֹ וּמָשְׁלוֹ מִיָּם עַד יָם, וְלֹא מָצִינוּ מוֹשֵׁל לְיִשְׂרָאֵל כָּזֶה בִּימֵי בַּיִת שֵׁנִי:",1,0],[9,9,"צַדִּיק וְנוֹשָׁע. בַּה׳׃",2,0],[9,9,"עָנִי. עֲנְוְתָן:",3,0],[9,9,"וְרוֹכֵב עַל חֲמוֹר. מִדַּת עֲנָוָה הִיא:",4,0],[9,9,"וְעַל עַיִר. כְּמוֹ ״וַעֲיָרִים עֲשָׂרָה״ (בראשית לב:טז):",5,0],[9,10,"וְהִכְרַתִּי רֶכֶב. שֶׁלֹּא יִהְיוּ צְרִיכִין לָהּ:",1,0],[9,10,"וּמָשְׁלוֹ. וּמִמְשָׁל שֶׁלּוֹ:",2,0],[9,10,"מִיָּם וְעַד יָם. ״מִיַּמָּא וְעַד מַעֲרְבָא״, לְסוֹף הָעוֹלָם (בראשית רבה ע:יט):",3,0],[9,10,"וּמִנָּהָר. פְּרָת:",4,0],[9,11,"גַּם אַתְּ. תִּוָּשְׁעִי עִמּוֹ, כְּמוֹ שֶׁהוּא צַדִּיק וְנוֹשָׁע (זכריה ט:ט), כִּי בְדַם בְּרִיתֵךְ הֲרֵי נִבֵּאתִי לָכֶם לֶעָתִיד, וְגַם עַתָּה מִגָּלוּת בָּבֶל שֶׁאַתֶּם עַכְשָׁיו בְּתוֹכָהּ:",1,0],[9,11,"בְּדַם בְּרִיתֵךְ. בִּזְכוּת דַּם הַבְּרִית שֶׁנִּזְרַק עֲלֵיכֶם בְּסִינַי, הִנֵּה דַם הַבְּרִית אֲשֶׁר כָּרַת (שמות כד:ח):",2,0],[9,11,"שִׁלַּחְתִּי אֲסִירַיִךְ. מִן הַגָּלוּת (ויקרא רבה יט:ו)׃",3,0],[9,12,"שׁוּבוּ לְבִצָּרוֹן. לְכֹחֲכֶם וְלִכְבוֹדְכֶם, אַף עַל פִּי שֶׁאַתֶּם עַתָּה בִּרְשׁוּת מַלְכֵי פָּרַס, אַתֶּם אֲסִירֵי הַתִּקְוָה. אֲשֶׁר קִוִּיתֶם לִי עַד הֵנָּה לְמַלֹּאות דְּבָרַי לְקֵץ שִׁבְעִים שָׁנָה (ירמיה כט:י):",1,0],[9,12,"גַּם הַיּוֹם מַגִּיד מִשְׁנֶה אָשִׁיב לָךְ. עוֹד הַיּוֹם אֲנִי מַגִּיד לְךָ בְּשׂוֹרָה שְׁנִיָּה, לְבַד זוֹ שֶׁל בִּנְיָן. וּמַה הִיא הַגָּדָה הַשְּׁנִיָּה שֶׁאֲנִי שָׁב לִשְׁנוֹת לָכֶם?:",2,0],[9,13,"כִּי דָרַכְתִּי לִי יְהוּדָה. סוֹף שֶׁאַנְטִיוֹכוּס יִטֹּל הַמְּלוּכָה מִיַּד מַלְכֵי פָרַס וְיָרֵעוּ לָכֶם, וַאֲנִי אֶדְרֹךְ יְהוּדָה לִהְיוֹת לִי כְּקֶשֶׁת מִלְחָמָה, וְיִלָּחֲמוּ בְּאַנְטִיוֹכוּס בִּימֵי חַשְׁמוֹנָאִים:",1,0],[9,13,"קֶשֶׁת מִלֵּאתִי אֶפְרַיִם. מִקְרָא קָצָר הוּא, כְּמוֹ קֶשֶׁת מִלֵּאתִי יַד אֶפְרָיִם, כְּמוֹ ״וְיֵהוּא מִלֵּא יָדוֹ בַקֶּשֶׁת״ (מלכים ב ט:כד). אֶפְרָיִם יִהְיֶה לִי כְּאַשְׁפָּה מְלֵאָה חִצִּים:",2,0],[9,13,"וְעוֹרַרְתִּי בָנַיִךְ צִיּוֹן. עַל חֵיל אַנְטִיוֹכוּס (פסיקתא רבתי ב):",3,0],[9,14,"וַה׳ עֲלֵיהֶם יֵרָאֶה. בְּסֵפֶר יוֹסִיפוֹן מָצִינוּ: בָּעֵת הַהִיא נִרְאָה מוֹפֵת לְאַנְשֵׁי יְרוּשָׁלָיִם:",1,0],[9,14,"בַּשּׁוֹפָר יִתְקָע. יִרְעַם:",2,0],[9,14,"בְּסַעֲרוֹת תֵּימָן. לְסַעֵר אֶת אַנְשֵׁי תֵימָן, הֵם חֵיל אַנְטִיוֹכוּס. וְיֵשׁ מֵרַבּוֹתֵינוּ (ירושלמי תענית ב,ד) שֶׁפָּתְרוּהוּ עַל אֱדוֹם, לֶעָתִיד לָבֹא:",3,0],[9,15,"וְאָכְלוּ. שְׁלַל אוֹיְבֵיהֶם:",1,0],[9,15,"וְכָבְשׁוּ. תַּחְתֶּיהָ אַבְנֵי קֶלַע, הֵם הַיְּוָנִים שֶׁהֵם מְלֻמְּדֵי קֶשֶׁת וְלִקְלֹעַ בָּאֶבֶן:",2,0],[9,15,"וְהָמוּ כְּמוֹ יָיִן. הֲמִיּוֹן בְּקוֹל שָׂשׂוֹן וְשִׂמְחָה, כְּמוֹ שֶׁהוֹמִים שְׁתוּיֵי יָיִן:",3,0],[9,15,"וּמָלְאוּ. נַפְשׁוֹתָם כָּל טוֹב:",4,0],[9,15,"כַּמִּזְרָק. שֶׁמָּלֵא דָם לִפְנֵי הַמִּזְבֵּחַ:",5,0],[9,15,"כְּזָוִיּוֹת מִזְבֵּחַ. שֶׁמְּנַסְּכִין שָׁם יַיִן וְהַיַּיִן צָף עָלָיו כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת סֻכָּה (סוכה מט:) לְשׁוֹן שְׂבִיעָה לְשׁוֹן שִׁכְרוּת:",6,0],[9,16,"כְּצֹאן עַמּוֹ. כַּצֹּאן שֶׁהִסִּיעַ מִמִּצְרַיִם לִהְיוֹת לוֹ לְעָם:",1,0],[9,16,"כִּי אַבְנֵי נֵזֶר. כִּי הַכֹּהֲנִים בְּנֵי חַשְׁמוֹנָאִים הַמִּתְפָּאֲרִים בְּאַבְנֵי נֵזֶר בְּטוּרֵי חֹשֶׁן וְאֵפוֹד יִהְיוּ מִתְנוֹסְסִים בְּנִסִּים עַל אַדְמָתָן:",2,0],[9,17,"כִּי מַה. רַב טוּבוֹ. הַצָּפוּן שֶׁל אוֹתוֹ הַדּוֹר:",1,0],[9,17,"דָּגָן בַּחוּרִים. הַנּוֹתֵן כֹּחַ לַבַּחוּרִים:",2,0],[9,17,"וְתִירוֹשׁ. אֲשֶׁר יְנוֹבֵב בְּתוּלוֹת בְּנִיב שִׁיר וְשִׂמְחָה. וְיֵשׁ פּוֹתְרִין אֲשֶׁר יְנוֹבֵב וְיִצְמַח בְּקַרְקַע בְּתוּלָה, וְהוּא יַיִן מְשֻׁבָּח:",3,0],[10,1,"שַׁאֲלוּ מֵה׳ מָטָר. אִם תִּצְטָרְכוּ:",1,0],[10,1,"חֲזִיזִים. עֲנָנִים מְבִיאִים מָטָר:",2,0],[10,1,"לְאִישׁ עֵשֶׂב בַּשָּׂדֶה. בִּשְׁבִיל אִישׁ אֶחָד וּבִשְׁבִיל עֵשֶׂב אֶחָד הַצָּרִיךְ לְמָטָר (תענית ט:):",3,0],[10,2,"כִּי הַתְּרָפִים. וְהַקּוֹסְמִים חָזוּ שֶׁקֶר וְהַחֲלוֹמוֹת אֲשֶׁר הִטְעוּ אֶת אֲבוֹתֵיכֶם ״לֵאמֹר חָלַמְתִּי״ (ירמיה כג:כה) וְהָיוּ מַחֲזִיקִים יְדֵיהֶם לִמְרֹד בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, דִּבְּרוּ אָוֶן וְהֶבֶל דִּבְּרוּ לֵאמֹר ״שָׁלוֹם וְאֵין שָׁלוֹם״ (ירמיה ו:יד):",1,0],[10,2,"עַל כֵּן נָסְעוּ. אֲבָל אֲנִי נָבִיא לָהֶם בֶּאֱמֶת:",2,0],[10,2,"יַעֲנוּ. יִתְכַּנְּעוּ, כְּמוֹ ״לֵעָנֹת מִפְּנֵי״ (שמות י:ג) – לְשׁוֹן עֹנִי:",3,0],[10,3,"עַל הָרֹעִים חָרָה אַפִּי. עַל מַלְכֵי נְבוּכַדְנֶצַּר וְסַנְחֵרִיב (נוסח אחר: מַלְכֵי יָוָן):",1,0],[10,3,"וְעַל הָעַתּוּדִים. עַל שָׂרֵיהֶם, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וְעַל מַלְכַיָּא הֲוָה רוּגְזִי וְעַל שָׁלְטָנַיָּא אֲנָא מְסָעֵר״. וְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת נִמְשְׁלוּ לַעֲתוּדִים: ״וְהַצָּפִיר הַשָּׂעִיר מֶלֶךְ יָָוָן״ (דניאל ח:כא). וְהָרוֹצֶה לְפָרֵשׁ הָעִנְיָן שֶׁלֹּא בְּמַלְכֵי עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יֹאמַר: עַתּוּדִים – לְשׁוֹן שָׂרִים, כְּמוֹ ״עוֹרֵר לְךָ רְפָאִים כָּל עַתּוּדֵי אָרֶץ״ (ישעיה יד:ט):",2,0],[10,3,"כְּסוּס הוֹדוֹ בַּמִּלְחָמָה. כְּסוּס אֲשֶׁר יֻכַּר הוֹדוֹ בַּמִּלְחָמָה:",3,0],[10,4,"מִמֶּנּוּ פִנָּה. מֵהֶם מַלְכֵיהֶם, מֵהֶם שָׂרֵיהֶם, מֵהֶם לוֹחֲמֵי מִלְחֲמוֹתָם (חולין נו:):",1,0],[10,5,"וְהָיוּ כְגִבּוֹרִים בּוֹסִים בְּטִיט חוּצוֹת בַּמִּלְחָמָה. הֲרֵי מִקְרָא זֶה מְסֹרָס, וְהָיוּ בַּמִּלְחָמָה הוֹלְכִים וְדוֹרְכִים אֲנָשִׁים כְּגִבּוֹרִים הַבּוֹסִים טִיט חוּצוֹת. בּוֹסִים – דּוֹרְסִים, כְּמוֹ ״יָבוּס קָמֵינוּ״ (תהילים מד:ו), ״בּוֹסְסוּ אֶת חֶלְקָתִי״ (ירמיהו יב:י):",1,0],[10,5,"וְהוֹבִישׁוּ. בֵּית יְהוּדָה, אֶת רוֹכְבֵי הַסּוּסִים הַבָּאִים לְהִלָּחֵם בָּם:",2,0],[10,6,"וְגִבַּרְתִּי אֶת בֵּית יְהוּדָה. בְּמִלְחֶמֶת הַיְּוָנִים:",1,0],[10,6,"וְאֶת בֵּית יוֹסֵף אוֹשִׁיעַ. בַּמָּקוֹם שֶׁגָּלוּ שָׁם בַּחֲלַח וּבְחָבוֹר בִּימֵי סַנְחֵרִיב (מלכים ב יח:יא):",2,0],[10,6,"וְהוֹשְׁבוֹתִים. כְּמוֹ וְהוֹשַׁבְתִּים, לְשׁוֹן יְשִׁיבָה:",3,0],[10,6,"וְהָיוּ כַּאֲשֶׁר לֹא זְנַחְתִּים. כְּאִלּוּ לֹא זְנַחְתִּים מֵעוֹלָם:",4,0],[10,8,"אֶשְׁרְקָה לָהֶם. כְּדֶרֶךְ הַשּׁוֹרְקִים לְסִימָן אוֹת לָבֹא אֵלָיו הַטּוֹעֶה בַּדֶּרֶךְ:",1,0],[10,8,"וַאֲקַבְּצֵם. לְעֵת הַקֵּץ, לֶעָתִיד:",2,0],[10,8,"כִּי פְדִיתִים. כְּשֶׁאֶפְדֵּם:",3,0],[10,8,"וְרָבוּ. בַּגּוֹלָה כְּמוֹ שֶׁרָבוּ בְּמִצְרָיִם (שמות א:ז):",4,0],[10,9,"וְאֶזְרָעֵם. תְּחִלָּה בָּעַמִּים, כְּאָדָם הַזּוֹרֵעַ סְאָה לְהַכְנִיס כַּמָּה כּוֹרִין (פסחים פז:):",1,0],[10,9,"וְחָיוּ אֶת בְּנֵיהֶם. עִם בְּנֵיהֶם:",2,0],[10,10,"וּלְבָנוֹן. זֶה בֵּית הַמִּקְדָּשׁ (יומא לט:):",1,0],[10,10,"וְלֹא יִמָּצֵא לָהֶם. ״וְלֹא יִסֻפָּק לְהוֹן״ (תרגום יונתן):",2,0],[10,11,"וְעָבַר בַּיָּם צָרָה. וְתַעֲבֹר צָרָה בְּצוֹר הַיּוֹשֶׁבֶת בְּתוֹךְ הַיָּם, וְהוּא רֹאשׁ לְמַלְכוּת צוֹר:",1,0],[10,11,"וְהִכָּה. הַקָּדוֹשׁ בָּרוּךְ הוּא אֲשֶׁר הוּא הַמַּכֶּה יַכֶּה בַיָּם גַּלִּים לְהַשְׁקִיעַ אֶת צוֹר:",2,0],[10,11,"כָּל מְצוּלוֹת יְאוֹר. הִיא מִצְרָיִם:",3,0],[11,1,"פְּתַח לְבָנוֹן דְּלָתֶיךָ. תִּרְגֵּם יוֹנָתָן: ״פִּתְחוּ עַמְמַיָּא תַּרְעֵיכוֹן״:",1,0],[11,2,"הֵילֵל בְּרוֹשׁ כִּי נָפַל אֶרֶז. שֶׁהוּא גָּדוֹל מִן הַבְּרוֹשׁ. הֵילִילוּ הַשִּׁלְטוֹנִים כִּי נָפְלוּ הַמְּלָכִים מֵעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[11,2,"אַלּוֹנֵי בָשָׁן. קִישְׁנֵ״שׁ בְּלַעַ״ז:",2,0],[11,2,"כִּי יָרַד. כִּי נִשְׁבַּר, וְדוֹמֶה לוֹ ״וּבָרַד בְּרֶדֶת הַיַּעַר״ (ישעיה לב:יט):",3,0],[11,2,"יַעַר הַבָּצִיר. יַעַר הַמִּבְצָר, ״תְּקוֹף כַּרְכַיָּא״:",4,0],[11,3,"הָרוֹעִים. הַמְּלָכִים:",1,0],[11,3,"אַדַּרְתָּם. תִּפְאַרְתָּם׃",2,0],[11,3,"שַׁאֲגַת כְּפִירִים. יִבְכּוּ הַשָּׂרִים:",3,0],[11,3,"כִּי שֻׁדַּד גְּאוֹן הַיַּרְדֵּן. שֶׁהוּא מְקוֹם הַכְּפִירִים וַאֲרָיוֹת. וְרַבּוֹתֵינוּ פֵּרְשׁוּ פְּתַח לְבָנוֹן דְּלָתֶיךָ (יומא לט:), שֶׁעַל חֻרְבַּן בַּיִת שֵׁנִי נִתְנַבֵּא הַנָּבִיא, וְאַרְבָּעִים שָׁנָה קֹדֶם חֻרְבָּן הָיוּ דַּלְתוֹת הַהֵיכָל נִפְתָּחוֹת מֵאֲלֵיהֶן. גָּעַר בָּהֶן רַבִּי יוֹחָנָן בֶּן זַכַּאי, אָמַר לוֹ: הֵיכָל הֵיכָל, עַד מָתַי אַתָּה מְבַעִית אֶת עַצְמְךָ? יוֹדֵעַ אֲנִי שֶׁסּוֹפְךָ לֵחָרֵב, וּכְבָר נִתְנַבֵּא עָלֶיךָ זְכַרְיָה בֶּן עִדּוֹא פְּתַח לְבָנוֹן דְּלָתֶיךָ וְגוֹ׳:",4,0],[11,4,"רְעֵה אֶת צֹאן הַהֲרֵגָה. הָכֵן לָהֶם רוֹעִים, כְּלוֹמַר: הִנָּבֵא עַל פַּרְנָסֵיהֶם הָעֲתִידִים לִרְעוֹתָם מֵעַתָּה:",1,0],[11,4,"צֹאן הַהֲרֵגָה. יִשְׂרָאֵל שֶׁהֲרָגוּם רוֹעֵיהֶם וַאֲכָלוּם:",2,0],[11,5,"וְלֹא יֶאְשָׁמוּ. הַבַּבְלִיִּים שֶׁאַגְלֵם לְתוֹכָם, זֶה מוֹכְרָם וְהַקּוֹנֶה הָרוּג, וְאֵין נוֹתֵן לְלִבּוֹ שֶׁיְּהֵא לוֹ אַשְׁמָה בַּדָּבָר. וּמוֹכְרָם מִתְהַלֵּל: בָּרוּךְ ה׳ שֶׁמְּסָרָם בְּיָדִי, וַהֲרֵינִי עָשִׁיר:",1,0],[11,5,"וַאעְשִׁר. וַהֲרֵי אֲנִי עָשִׁיר:",2,0],[11,7,"וָאֶרְעֶה אֶת צֹאן הַהֲרֵגָה. כָּל אֵלֶּה דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּבִיא, וַאֲנִי רָעִיתִי אוֹתָם בַּיָּמִים הַקַּדְמוֹנִים:",1,0],[11,7,"לָכֵן עֲנִיֵּי הַצֹּאן. אֱמֶת עֲנִיֵּי הַצֹּאן הָיוּ כְּשֶׁהִתְחַלְתִּי לִרְעוֹתָם:",2,0],[11,7,"וָאֶקַּח לִי שְׁנֵי מַקְלוֹת. לְסוֹף יָמִים חִלַּקְתִּים לִשְׁתֵּי מַמְלָכוֹת בַּעֲוֹנָם:",3,0],[11,7,"לְאַחַד קָרָאתִי נֹעַם. יָרָבְעָם אָמַר לְנַהֲלָם לְאַט:",4,0],[11,7,"וּלְאַחַד קָרָאתִי חוֹבְלִים. רְחַבְעָם אָמַר לָהֶם לְיַסְּרָם בְּעַקְרַבִּים (מלכים א יב:יד). וּלְפִי שֶׁדֶּרֶךְ צֹאן לְנַהֲלָן בְּמַקְלוֹת, קָרָא לְמוֹשְׁלֵיהֶם מַקְלוֹת:",5,0],[11,8,"וָאַכְחִיד אֶת שְׁלֹשֶׁת הָרוֹעִים בְּיֶרַח אֶחָד. וְהֵם הִשְׁחִיתוּ דַרְכֵיהֶם עַד שֶׁמְאַסְתִּים וַהֲרַגְתִּים בְּחֹדֶשׁ אֶחָד. כָּל שְׁלֹשֶׁת הָרוֹעִים שֶׁהָרַג וְהוּא אֶת כָּל בֵּית אַחְאָב וְאֶת בֵּית אֲחַזְיָה מֶלֶךְ יְהוּדָה וְאֶת אֶחָיו וְאֶת כָּל זֶרַע מַלְכוּת דָּוִד, וַעֲתַלְיָה אִבְּדָה אֶת הַשְּׁאָר, זוּלָתִי יוֹאָשׁ שֶׁנִּטְמַן (מלכים ב יא:א-ג):",1,0],[11,8,"וַתִּקְצַר נַפְשִׁי בָּהֶם. מְאַסְתִּים. וְכָל לְשׁוֹן קֹצֶר נֶפֶשׁ הוּא דְּבַר צָרָה אוֹ דְּבַר מֵאוּס שֶׁאֵין הַדַּעַת סוֹבַלְתּוֹ, וְקָצַר הַלֵּב וְהַמֵּעַיִם מִלְּהָכִיל; כְּמוֹ שֶׁאֱלִיהוּ אָמַר: ״הֱצִיקַתְנִי רוּחַ בִּטְנִי״ (אִיּוֹב לב:יח):",2,0],[11,8,"גַּם נַפְשָׁם בָּחֲלָה בִי. זִכְרוֹנָם הָיָה רַב בְּמֵעַי וּמְמַלֵּא אֶת רוּחִי וּמֵצִיק אֶת בִּטְנִי. וּבָחֲלָה פֵּרְשׁוּ רַבּוֹתֵינוּ לְשׁוֹן גֹּדֶל בְּמַסֶּכֶת נִדָּה (נדה מז.): מָשָׁל מָשְׁלוּ חֲכָמִים בָּאִשָּׁה פַּגָּה בֹּחַל וְצֶמֶל, פַּגָּה עוֹדָהּ תִּינוֹקֶת, בֹּחַל אֵלּוּ יְמֵי הַנְּעוּרִים שֶׁכְּבָר הִיא גְּדוֹלָה. וְהֵבִיאוּ מִקְרָא זֶה רְאָיָה לְדִבְרֵיהֶם:",3,0],[11,9,"וָאֹמַר לֹא אֶרְעֶה אֶתְכֶם. אָמַרְתִּי בְּאוֹתָן הַיָּמִים אַשְׁלִיכֵם מֵעַל פָּנַי וְיִהְיוּ הֶפְקֵר וּלְבַז:",1,0],[11,10,"וָאֶקַּח אֶת מַקְלִי אֶת נֹעַם. שָׁבַרְתִּי אֶת כֹּחַ מַלְכֵי יִשְׂרָאֵל בִּימֵי יְהוֹאָחָז בֶּן יֵהוּא, עַד כִּי אִבְּדָם מֶלֶךְ אֲרָם וַיְשִׂימֵם כֶּעָפָר לָדוּשׁ (מלכים ב יג:ז). וּבִימֵי הוֹשֵׁעַ בֶּן אֵלָה, שֶׁמְּסַרְתִּים בְּיַד סַנְחֵרִיב וְהִגְלָהוּ (שם יז):",1,0],[11,10,"לְהָפֵר אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי אֶת כָּל הָעַמִּים. לְהַרְאוֹתָם, שֶׁבִּשְׁבִיל שֶׁבָּגְדוּ בִּי הֵפַרְתִּי אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי עִם כָּל הָעַמִּים עֲלֵיהֶם שֶׁלֹּא יַזִּיקוּם. שֶׁעַל מְנָת כֵּן נָתַתִּי לָהֶם אֶת הַתּוֹרָה, שֶׁאִם יִשְׁמְרוּהָ, שֶׁיִּהְיוּ חֵרוּת מִן הַמַּלְכֻיּוֹת; שֶׁלֹּא תְּהֵא אֻמָּה וְלָשׁוֹן שׁוֹלֶטֶת בָּהֶם (ערובין נד.). וְאַל תִּתְמַהּ אִם דִּבֵּר הַמִּקְרָא תְּשׁוּעָתָם מִיַּד שׂוֹנֵא בִּלְשׁוֹן כְּרִיתַת בְּרִית אֶת הַשּׂוֹנֵא, שֶׁהֲרֵי מָצִינוּ מִקְרָא דֻּגְמָתוֹ: ״וְכָרַתִּי לָהֶם בְּרִית בַּיּוֹם הַהוּא עִם חַיַּת הַשָּׂדֶה וְגוֹמֵר״ (הושע ב:כ):",2,0],[11,11,"וַיֵּדְעוּ. כֵּן הֵבִינוּ הַצַּדִּיקִים שֶׁבָּהֶם הַשּׁוֹמְרִים אֶת חוּקִּי:",1,0],[11,11,"כִּי דְבַר ה׳ הוּא. גְּזֵרָה זוֹ כְּבָר דִּבֵּר לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי מֹשֶׁה: ״יוֹלִיךְ ה׳ אֹתְךָ וְאֶת מַלְכְּךָ״ (דברים כח:לו):",2,0],[11,12,"וָאֹמַר. אֶל מַלְכֵי יְהוּדָה הַנּוֹתָרִים:",1,0],[11,12,"אִם טוֹב בְּעֵינֵיכֶם הָבוּ שְׂכָרִי. קַיְּמוּ מִצְוֹתַי, וְהוּא יִהְיֶה שְׂכָרִי עַל כָּל הַטּוֹבָה אֲשֶׁר נָתַתִּי לָכֶם, כְּמוֹ שֶׁנּוֹתְנִין שָׂכָר לְרוֹעֵה צֹאן, וְאָשׁוּב וְאֶרְעֶה אֶתְכֶם:",2,0],[11,12,"וְאִם לֹא חֲדָלוּ. וְגַם אֲנִי לֹא אֵיטִיב לָכֶם. וְכֵן מָצִינוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיחֶזְקֵאל: ״הַשּׁוֹמֵעַ יִשְׁמַע וְהֶחָדֵל יֶחְדָּל״ (יחזקאל ג:כז):",3,0],[11,12,"וַיִּשְׁקְלוּ אֶת שְׂכָרִי שְׁלֹשִׁים כָּסֶף. תִּרְגֵּם יוֹנָתָן: ״וַעֲבַדוּ יָת רְעוּתִי גֻּבְרִין מִקְצָת״ – אֲנָשִׁים טוֹבִים מְעַט הָיוּ בָּהֶם שֶׁעָשׂוּ רְצוֹנִי, כְּגוֹן ״הֶחָרָשׁ וְהַמַּסְגֵּר״ (מלכים ב כד:טז), דָּנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, יְחֶזְקֵאל. וּלְשׁוֹן שְׁלֹשִׁים כָּסֶף – לֹא יָדַעְתִּי לְכַוֵּן כָּאן אֶלָּא כֶּסֶף – לְשׁוֹן חֶמְדָּה. וְאַף רַבּוֹתֵינוּ פֵּרְשׁוּהוּ כֵּן בִּחֻלִּין (חולין צב.), וְהֵבִיאוּ רְאָיָה: ״צְרוֹר הַכֶּסֶף לָקַח בְּיָדוֹ״ (משלי ז:כ). וְאֶת הַשְּׁלֹשִׁים פֵּרְשׁוּ, שֶׁאַרְבָּעִים וַחֲמִשָּׁה צַדִּיקִים יֵשׁ בְּכָל דּוֹר וָדוֹר; וְהֵבִיאוּ רְאָיָה: ״וְחֹמֶר שְׂעֹרִים וְלֶתֶךְ שְׂעֹרִים״ (הושע ג:ב) – חֲמִשָּׁה עָשָׂר בְּבָבֶל; וּשְׁלֹשִׁים בְּאֶרֶץ יִשְׂרָאֵל, שֶׁנֶּאֱמַר ״וָאֶקְחָה אֶת שְׁלֹשִׁים הַכֶּסֶף בֵּית ה׳״ – בְּאֶרֶץ יִשְׂרָאֵל. וּמִנְיַן הַשְּׁלֹשִׁים – מִדְרַשׁ אַגָּדָה הוּא (תנחומא מקץ ו), שֶׁהֻבְטַח אַבְרָהָם אָבִינוּ בְּכָךְ שֶׁלֹּא יְהֵא דּוֹר פָּחוֹת מִשְּׁלֹשִׁים צַדִּיקִים. מִנְיָן? ״כֹּה יִהְיֶה זַרְעֶךָ״ (בראשית טו:ה) – ״יִהְיֶה״ בְּגִימַטְרִיָּא שְׁלֹשִׁים:",4,0],[11,13,"וַיֹּאמֶר ה׳ אֵלַי הַשְׁלִיכֵהוּ אֶל הַיּוֹצֵר. כְּמוֹ אֶל הָאוֹצָר, שׁוֹמֵר הָאוֹצָר. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּבִיא: כְּתֹב וְהַנַּח אֶת אֵלּוּ, הֵם וְצִדְקָתָם, לִהְיוֹת שָׁמוּר לְסוֹף שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל, וְיִבָּנֶה בֵּית הַמִּקְדָּשׁ עַל יְדֵיהֶם. וּמַהוּ הָאוֹצָר? אֶדֶר הַיְקָר בֵּית מִקְדָּשִׁי, אֲדַר תִּפְאַרְתִּי:",1,0],[11,13,"אֲשֶׁר יָקַרְתִּי מֵעֲלֵיהֶם. אֲשֶׁר הִפְשַׁטְתִּי מֵעֲלֵיהֶם מִהְיוֹת לָהֶם לִיקָר. וּלְשׁוֹן יָקַרְתִּי הוּא הֲסָרַת כָּבוֹד, וְהַמֵּ״ם שֶׁל מֵעֲלֵיהֶם יוֹכִיחַ. וְהוּא כְּמוֹ ״וְשֵׁרֶשְׁךָ מֵאֶרֶץ חַיִּים״ (תהלים נב:ז), כְּמוֹ ״מְסָעֵף פֹּארָה״ (ישעיהו י:לג). וְדֻגְמַת הַפֵּרוּשׁ שֶׁפֵּרַשְׁתִּי, מֵעֵין תַּרְגּוּם שֶׁל יוֹנָתָן הוּא. וְרָאִיתִי לְשׁוֹנוֹת הַרְבֵּה לְפֵרוּשׁ נְבוּאָה זוֹ, וְאֵינִי יָכוֹל לְכַוְּנָן:",2,0],[11,14,"וָאֶגְדַּע אֶת מַקְלִי הַשֵּׁנִי. הִגְלֵיתִי אֶת צִדְקִיָּהוּ:",1,0],[11,14,"אֶת הַחוֹבְלִים. אֶת רִשְׁעֵי דּוֹרוֹ, כִּי הוּא צַדִּיק וְדוֹרוֹ רְשָׁעִים (סנהדרין קג.):",2,0],[11,14,"לְהָפֵר אֶת הָאַחֲוָה. שֶׁנִּתְאַחֲווּ בְּנֵי יְהוּדָה וּבִנְיָמִן וְנִדְבְּקוּ בְּתוֹעֲבוֹת מַלְכֵי יִשְׂרָאֵל:",3,0],[11,15,"עוֹד קַח לְךָ וְגוֹ׳. וְזֶהוּ שֶׁאָמַר לוֹ לְמַעְלָה רְעֵה צֹאן הַהֲרֵגָה, סִימָן הוּא שֶׁאֲנִי עָתִיד לִמְסֹר דּוֹר חֻרְבַּן בַּיִת שֵׁנִי זֶה בְּיַד טִיטוּס:",1,0],[11,16,"הַנִּכְחָדוֹת. הָאוֹבְדוֹת לֹא יִפְקֹד הָרוֹעֶה לְבַקְּשָׁם:",1,0],[11,16,"הַנַּעַר לֹא יְבַקֵּשׁ. תִּרְגֵּם יוֹנָתָן ״דְּאִטַּלְטְלוּ לָא יִתְבַּע״. הַנַּעַר – הַשּׁוֹטוֹת שֶׁאֵינָן יוֹדְעוֹת לָבוֹא אֶל הַדִּיר:",2,0],[11,16,"הַנִּצָּבָה. שֶׁיֵּשׁ לָהּ כֹּחַ קְצָת לַעֲמֹד עַל רַגְלֶיהָ, וּצְרִיכָה סִיּוּעַ לְנַהֲלָהּ לְאַט. וּמְנַחֵם פֵּרֵשׁ וְנִצָּבָה לְשׁוֹן ״לַצְבּוֹת בֶּטֶן״ (במדבר ה:כב):",3,0],[11,16,"לֹא יְכַלְכֵּל. תִּרְגֵּם יוֹנָתָן: ״לָא יְסוֹבַר״, וְדֶרֶךְ הָרוֹעֶה בְּחֵיקוֹ יִשָּׂא (יְשַׁעְיָהוּ מ:יא):",4,0],[11,16,"וּבְשַׂר הַבְּרִיאָה יֹאכַל. אֶת הָעֲשִׁירִים יִגְמֹר מָמוֹנָן:",5,0],[11,16,"וּפַרְסֵיהֶן יְפָרֵק. עַד כָּלָה. וְדֻגְמַת זוֹ אָמַר דָּנִיֵּאל (דניאל ז:ז): ״אָכְלָה וּמַדֱּקָה וּשְׁאָרָא בְּרַגְלַהּ רָפְסָה״:",6,0],[11,17,"הוֹי. יֵשׁ לִצְעוֹק עַל זֶה:",1,0],[11,17,"רֹעִי הָאֱלִיל. רוֹעֵי שֶׁל אַיִן, אֱלִיל לְשׁוֹן אַל, אֵינוֹ רוֹעֶה. וְכֵן רֹפְאֵי אֱלִיל (איוב יג:ד). רֹעִי הָאֱלִיל יוֹ״ד יְתֵרָה בִּמְקוֹם הֵ״א, כְּמוֹ עֹזְבִי הַצֹּאן (כאן), ״שֹׁכְנִי סְנֶה״ (דְּבָרִים לג:טז), ״שֹׁכְנִי לְבָדָד״ (מִיכָה ז:יד):",2,0],[11,17,"עוֹזְבִי הַצֹּאן. נוֹתְנָן הֶפְקֵר לְיַד כָּל הַבָּא לְהַכּוֹת וְלַהֲרֹג וְלָבֹז:",3,0],[11,17,"חֶרֶב עַל זְרוֹעוֹ וְעַל עֵין יְמִינוֹ. וְהוּא הָרוֹעֶה סַכִּין שֶׁל שְׁחִיטָה נוֹשֵׂא בְּיָדוֹ לִשְׁחוֹט אֶת הַשְּׁמֵנָה וְאֶת הַבְּרִיאָה, שֶׁנָּתַן עֵין יְמִינוֹ בָּהֶם לָדַעַת מִי הָעֲשִׁירִים לָבֹז וְלִגְמוֹר נִכְסֵיהֶם:",4,0],[11,17,"זְרוֹעוֹ יָבוֹשׁ תִּיבָשׁ. לֶעָתִיד לָבֹא: ״וְנָתַתִּי נִקְמָתִי וְגוֹמֵר״ (יחזקאל כח:יד). וְהַפּוֹתְרִים פּוֹתְרִים אוֹתוֹ בְּצִדְקִיָּהוּ, עַל שֵׁם ״וְאֶת עֵינֵי צִדְקִיָּהוּ עִוֵּר״ (ירמיה כב:יא). וְאִי אֶפְשָׁר לְכַוֵּן ״הִנְנִי מֵקִים רָעָה בָּאָרֶץ״ בְּצִדְקִיָּהוּ, שֶׁכְּבָר עָבַר לוֹ שִׁבְעִים שָׁנָה:",5,0],[12,1,"מַשָּׂא דְבַר ה׳. הוּא גְּמַר זֶה הַדָּבָר שֶׁהִתְחִיל לְדַבֵּר בְּפֻרְעָנוּתָן שֶׁל אוֹכְלֵי יִשְׂרָאֵל עַל בָּבֶל וְכַיּוֹצֵא בּוֹ:",1,0],[12,2,"סַף רַעַל. כְּלִי תַּרְעֵלָה, כְּמוֹ ״בַּדָּם אֲשֶׁר בַּסַּף״ (שמות יב:כב). רַעַל לְשׁוֹן שִׁמָּמוֹן, אֹטֶם הַלֵּב וְהָאֵבָרִים שֶׁאֵין לָהֶם כֹּחַ, כְּאָדָם הַמְעֻטָּף בְּשִׂמְלָה, כְּמוֹ (נחום ב:ד) ״הַבְּרוֹשִׁים הָרְעָלוּ״, (ישעיה ג:יט) ״הַשֵּׁרוֹת וְהָרְעָלוֹת״. בִּלְשׁוֹן מִשְׁנָה (שבת ו,ו) מָצִינוּ מְדִיּוֹת רְעוּלוֹת, אונבלופמנט״א בְּלַעַ״ז:",1,0],[12,2,"וְגַם עַל יְהוּדָה. יַטִּילוּ הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֲשֶׁר יִהְיוּ בַּמָּצוֹר עַל יְרוּשָׁלִַם, שֶׁיִּהְיוּ בֵית דָּוִד מִבִּפְנִים וְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יָצוּרוּ עֲלֵיהֶם, וְיָבֹאוּ גַם בְּנֵי יְהוּדָה עַל כָּרְחָם לָצוּר עַל יְרוּשָׁלִַם. כֵּן תַּרְגּוּם יוֹנָתָן:",2,0],[12,3,"אֶבֶן מַעֲמָסָה. אֶבֶן מַשָּׂאוֹי הַמֻּטֶּלֶת עַל בְּנֵי אָדָם מִפִּי הַמּוֹשֵׁל לָשֵׂאתָהּ וּלְעָמְסָהּ עַל כְּתֵפַיִם, וְהִיא כְּבֵדָה מְאֹד עַד אֲשֶׁר כָּל עֹמְסֶיהָ שָׂרוֹט יִשָּׂרֵטוּ:",1,0],[12,4,"אַכֶּה כָל סוּס. הַצּוֹבְאִים שָׁם בַּשִּׁגָּעוֹן וְאֶת רֹכְבֵיהֶם בָּעִוָּרוֹן, אֲבָל עַל בֵּית יְהוּדָה שֶׁהֵם עַל כָּרְחָם מִן הַצּוֹבְאִים אֶפְקַח עֵינַי לְהָגֵן עֲלֵיהֶם מִן הַמַּכָּה הַזֹּאת:",1,0],[12,5,"וְאָמְרוּ אַלֻּפֵי יְהוּדָה בְּלִבָּם. כְּשֶׁיִּרְאוּ שְׁאָר הַצּוֹבְאִים נִגָּפִים בְּמַגֵּפָה זוֹ וְהֵם נִצּוֹלִים:",1,0],[12,5,"אַמְצָה לִי יֹשְׁבֵי יְרוּשָׁלִַם וְגוֹ׳. יוֹשְׁבֵי יְרוּשָׁלַיִם שֶׁיּוֹדְעִים שֶׁעַל כָּרְחֵנוּ אָנוּ בָּאִים עֲלֵיהֶם, אִמְּצוּ לְעֶזְרָתִי בִּתְפִלָּתָן בַּה׳ אֱלֹהֵיהֶם:",2,0],[12,6,"אָשִׂים אֶת אַלֻּפֵי יְהוּדָה. יָשׁוּבוּ וְיִלָּחֲמוּ עִם אוֹתָם שֶׁהֱבִיאוּם שָׁם:",1,0],[12,6,"כְּכִיּוֹר אֵשׁ. כִּמְדוּרוֹת אֵשׁ גְּדוֹלָה. וְכִיּוֹר לְשׁוֹן כִּירָה (ויקרא יא:לה), וְכָךְ חִבְּרוֹ מְנַחֵם:",2,0],[12,6,"תַּחְתֶּיהָ. בִּמְקוֹמָהּ:",3,0],[12,7,"וְהוֹשִׁעַ ה׳ אֶת אָהֳלֵי יְהוּדָה בָּרִאשׁוֹנָה. בְּטֶרֶם יָבוֹאוּ בְּנֵי יְרוּשָׁלַיִם לָצֵאת מִן הָעִיר, תִּהְיֶה לָהֶם תְּשׁוּעָה לָשׁוּב אֶל אָהֳלֵיהֶם וְאֶל בֵּיתָם. וְאַחַר כָּךְ תָּבֹא תְּשׁוּעָה לִבְנֵי הָעִיר, הִיא הַתְּשׁוּעָה שֶׁנֶּאֱמַר בָּהּ ״וְיָצָא ה׳ וְנִלְחַם״ (זכריה יד:ג):",1,0],[12,7,"לְמַעַן לֹא תִגְדַּל. לְהִתְפָּאֵר עֲלֵיהֶם וְלוֹמַר: לֹא נִצַּלְתֶּם אֶלָּא בִּשְׁבִילֵנוּ:",2,0],[12,8,"הַנִּכְשָׁל בָּהֶם. הַחַלָּשׁ שֶׁבָּהֶם:",1,0],[12,8,"כֵּאלֹהִים. ״כְּרַבְרְבִין״ (תרגום יונתן), כְּמַלְאָכִים:",2,0],[12,8,"כְּמַלְאַךְ ה׳ לִפְנֵיהֶם. ״יִצְלְחוּן כְּמַלְאֲכָא דַה׳ קֳדָמֵיהוֹן״ (תרגום יונתן):",3,0],[12,9,"אֲבַקֵּשׁ לְהַשְׁמִיד. אֲבַקֵּשׁ בְּהַשְׁמָדָתָם וַאֲדַקְדֵּק בַּעֲוֹנָם. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לִזְכוּת (עבודה זרה ד.): אֲבַקֵּשׁ בְּנוֹגְנֵי שֶׁלָּהֶם; אִם יֵשׁ לָהֶם זְכוּת – אֲנִיחֵם, וְאִם לָאו – אַשְׁמִידֵם:",1,0],[12,10,"רוּחַ חֵן וְתַחֲנוּנִים. שֶׁיַּעֲלֶה עַל רוּחָם לְהִתְחַנֵּן לְפָנַי, וְהֵם יִהְיוּ לְחֵן בְּעֵינַי:",1,0],[12,10,"רוּחַ. טָלַנְ״ט בְּלַעַ״ז:",2,0],[12,10,"וְהִבִּיטוּ אֵלַי אֵת אֲשֶׁר דָּקָרוּ. תִּרְגֵּם יוֹנָתָן: ״וְיִבְעוֹן מִן קֳדָמַי עַל דִּי אִיטַלְטְלוּ״:",3,0],[12,10,"וְהִבִּיטוּ. לְהִתְאוֹנֵן עַל אֲשֶׁר דָּקְרוּ בָּהֶם הָאֻמּוֹת וְהָרְגוּ בָּהֶם בַּגָּלוּת:",4,0],[12,10,"וְסָפְדוּ עָלָיו. עַל אוֹתוֹ הֶרֶג:",5,0],[12,10,"כְּמִסְפֵּד עַל הַיָּחִיד. כַּאֲשֶׁר יִסְפֹּד אִישׁ עַל בֵּן יְחִידוֹ. וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ עַל מָשִׁיחַ בֶּן יוֹסֵף שֶׁנֶּהֱרַג בִּמְסֶכֶת סֻכָּה (סוכה נב.):",6,0],[12,11,"כְּמִסְפַּד הֲדַדְרִמּוֹן בְּבִקְעַת מְגִדּוֹן. אֵין עִנְיַן הֲדַדְרִימּוֹן בְּבִקְעַת מְגִדּוֹן, אֶלָּא שְׁנֵי מִסְפָּדוֹת הֵן: ״כְּמִסְפְּדָא דְאַחְאָב בַּר עָמְרִי דְּקָטַל יָתֵיהּ הֲדַדְרִמּוֹן בַּר טַבְרִימוֹן ״בְּרָמוֹת גִּלְעָד, שֶׁנֶּאֱמַר (מלכים א כב:לו) ״וַיַּעֲבֹר הָרִנָּה בַּמַּחֲנֶה״, וְהוּא הֶסְפֵּד. ״וּכְמִסְפְּדָא דְיֹאשִׁיָּהוּ בַּר אָמוֹן דְּקָטַל יָתֵיהּ פַּרְעֹה חֲגִירָא בְּבִקְעַת מְגִדּוֹן״, שֶׁנֶּאֱמַר שָׁם (דברי הימים ב לה:כה) ״וַיְקוֹנֵן יִרְמְיָהוּ וְגוֹ׳ וַיֹּאמְרוּ כָל הַשָּׂרִים וְהַשָּׁרוֹת בְּקִינוֹתֵיהֶם וְגוֹ׳״:",1,0],[12,12,"בֵּית נָתָן. הַנָּבִיא. וְיֵשׁ אוֹמְרִים: נָתָן בֶּן דָּוִד, כְּמוֹ שֶׁנֶּאֱמַר: ״שַׁמּוּעַ וְשׁוֹבָב וְנָתָן וּשְׁלֹמֹה״ (שמואל ב ה:יד):",1,0],[12,13,"בֵּית לֵוִי. הַכֹּהֲנִים וְהַלְוִיִּם:",1,0],[12,13,"מִשְׁפַּחַת הַשִּׁמְעִי. שַׁמּוּעַ בֶּן דָּוִד (שמואל ב ה:יד), בִּתְחִלָּה כָּלַל הַכָּתוּב מִשְׁפְּחוֹת בֵּית דָּוִד וְאַחַר כָּךְ פֵּרַט כָּל אַחַת וְאַחַת:",2,0],[12,14,"כָּל הַמִּשְׁפָּחוֹת הַנִּשְׁאָרוֹת. לְבֵית דָּוִד:",1,0],[12,14,"וּנְשֵׁיהֶם לְבָד. מִשּׁוּם צְנִיעוּת (סוכה נא:-נב.). וְלָמָּה מִשְׁפְּחוֹת הַכְּהוּנָּה וְהַמַּמְלָכוּת? כְּדֵי לְהַחֲזִיר לָהֶם כִּתְרֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר בְּרֹאשׁ הַסֵּפֶר ״אֵלֶּה שְׁנֵי בְנֵי הַיִּצְהָר הָעֹמְדִים עַל אֲדוֹן כָּל הָאָרֶץ״ (זכריה ד:יד):",2,0],[13,1,"לְחַטַּאת וּלְנִדָּה. לְאַדְיוּתָא, וְכֵן תִּרְגֵּם יוֹנָתָן: ״אֶשְׁבּוֹק לְחוֹבֵיהוֹן כְּמָא דְמִדְכָּן בְּמֵי אַדְיוּתָא וּבְקִטְם תּוֹרְתָא דְחַטָּאתָא״ – בְּאֵפֶר חַטָּאת:",1,0],[13,2,"וְגַם אֶת הַנְּבִיאִים. ״נְבִיאֵי שִׁקְרָא״:",1,0],[13,2,"רוּחַ הַטֻּמְאָה. יֵצֶר הָרָע:",2,0],[13,4,"אַדֶּרֶת שֵׂעָר. כֵּן דֶּרֶךְ מְסִיתִים וּמַדִּיחִים, מִתְעַטְּפִים בְּטַלִּיתָם כְּאִלּוּ הֵם אֲנָשִׁים צַדִּיקִים, לְמַעַן יְקֻבְּלוּ כַּחֲשֵׁיהֶם:",1,0],[13,5,"כִּי אָדָם הִקְנַנִי. פָּתַר בּוֹ מְנַחֵם לְשׁוֹן מִקְנֵה צֹאן וּבָקָר (בראשית כו:יד), כִּי אֲנִי כִּשְׁאָר כָּל אָדָם שֶׁאֵינוֹ עָסוּק בִּנְבוּאוֹת, הִפְקִידַנִי מִנְּעוּרַי לִשְׁמֹר אֶת מִקְנֵהוּ:",1,0],[13,6,"בֵּין יָדֶיךָ. בֵּין כְּתֵפֶיךָ, שָׁם מַלְקִין עוֹבְרֵי עֲבֵירָה (מכות כב.):",1,0],[13,6,"בֵּית מְאַהֲבָי. אֲשֶׁר אֲהָָבוּנִי וְהוֹכִיחוּנִי לַדֶּרֶךְ הַיְשָׁרָה:",2,0],[13,7,"חֶרֶב עוּרִי עַל רֹעִי. עַל אוֹתוֹ שֶׁהִפְקַדְתִּיו עַל צֹאן גָּלוּתִי:",1,0],[13,7,"וְעַל גֶּבֶר עֲמִיתִי. שֶׁחִבַּרְתִּיו אֵלַי לִשְׁמֹר צֹאנִי כָּמוֹנִי:",2,0],[13,7,"הַךְ אֶת הָרוֹעֶה. אֶת מֶלֶךְ רוֹמִי הָרְשָׁעָה:",3,0],[13,7,"וַתְּפוּצֶינָה הַצֹּאן. שֶׁכְּבוּשָׁה תַּחַת יָדוֹ:",4,0],[13,7,"וַהֲשִׁבֹתִי יָדִי. וְאֶשְׁנֶה מַכּוֹתַי שֵׁנִית:",5,0],[13,7,"עַל הַצּוֹעֲרִים. עַל הַשִּׁלְטוֹנִים הַצְּעִירִים מִן הַמְּלָכִים. וְיוֹנָתָן תִּרְגֵּם וַתְּפוּצֶינָה הַצֹּאן ״וְיִתְבַּדְּרוּן שִׁלְטוֹנַיָּא״, וְתִרְגֵּם עַל הַצּוֹעֲרִים מְמֻנִּים שֶׁלָּהֶם הַשְּׁנִיִּים לָהֶם, וְכֵן תִּרְגֵּם יוֹנָתָן הַמִּקְרָא הַזֶּה בָּאֻמּוֹת ״חַרְבָּא אִתְגְּלִי עַל מַלְכָּא דְבָבֶל וְעַל שִׁלְטוֹנַיָּא חַבְרֵיהּ דִּכְוָתֵיהּ דְּדָמֵי לֵיהּ אֲמַר ה׳ צְבָאוֹת קְטוֹל יַת מַלְכָּא דְבָבֶל וְיִתְבַּדְּרוּן שִׁלְטוֹנַיָּא״. וְאֵין לְשׁוֹן הַתַּרְגּוּם הַזֶּה נוֹפֵל עַל יִשְׂרָאֵל, שֶׁלֹּא מָצִינוּ בְּתַרְגּוּם וּבְמִקְרָא שִׁלְטוֹנִין בְּיִשְׂרָאֵל אֶלָּא מֶלֶךְ וְשָׂרִים וְתַרְגּוּם שֶׁלָּהֶן ״רַבְרְבִין״:",6,0],[13,8,"וְהַשְּׁלִישִׁית יִוָּתֶר בָּהּ. יִתְגַּיְּרוּ וְיִחְיוּ:",1,0],[13,9,"וְהֵבֵאתִי אֶת הַשְּׁלִישִׁית בָּאֵשׁ. ״וְאָעֵיל יָת תְּלִיתָא בְּעָקָא בְּכוּר דְּאֶשָּׁא״, שֶׁיִּסְבְּלוּ וְיִשְׂאוּ מִקְצָת הַגֵּרִים מֵהָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּצָרוֹת חֶבְלוֹ שֶׁל מָשִׁיחַ וּבְמִלְחֲמוֹת גּוֹג וּמָגוֹג עִם יִשְׂרָאֵל, וּמִשָּׁם יִבָּחֲנוּ כִּי גֵרֵי אֱמֶת הֵם. כִּי הַרְבֵּה מִן הַמִּתְיַהֲדִים תְּחִלָּה יָשׁוּבוּ לְסוּרָם וְיִתְחַבְּרוּ עִם גּוֹג, כְּמוֹ שֶׁאָמְרוּ בָּאַגָּדָה (עבודה זרה ג:):",1,0],[13,9,"וְהוּא יֹאמַר ה׳. כְּשֶׁיִּתְפַּלֵּל, יִתְפַּלֵּל לַה׳, וְלֹא לֵאלֹהָיו הָרִאשׁוֹן:",2,0],[14,1,"הִנֵּה יוֹם וְגוֹ׳. חָבִיב לְהַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[14,1,"וְחֻלַּק שְׁלָלֵךְ בְּקִרְבֵּךְ. שָׁלָל שֶׁתִּשְׁלְלִי מֵאוֹיְבִים יְחַלְּקוּ יוֹשְׁבַיִךְ בְּקִרְבֵּךְ. וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיפַלְּגוּן בֵּית יִשְׂרָאֵל נִכְסֵי עַמְמַיָּא בְּגַוִּיךְ יְרוּשְׁלֵם״:",2,0],[14,2,"וְיֶתֶר הָעָם לֹא יִכָּרֵת. לֹא יִגְלוּ כֻּלָּם. וְלָמָּה יַנִּיחֵם לְהַגְלוֹת חֶצְיָם וְלָשֹׁסוֹת הַבָּתִּים? כְּדֵי שֶׁלֹּא יְהֵא לָהֶם פִּתְחוֹן פֶּה לֵאמֹר: לֹא לַמִּלְחָמָה בָּאנוּ, כִּי אִם לְהִשְׁתַּחֲווֹת בָּאנוּ:",1,0],[14,3,"כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. ״כְּיוֹם אֲגָחוּתֵיהּ קְרָב עַל יַמָּא דְּסוּף״:",1,0],[14,4,"מֵחֶצְיוֹ. מֵאֶמְצָעִיתוֹ:",1,0],[14,4,"מִזְרָחָה וָיָמָּה. מִן הַמִּזְרָח לַמַּעֲרָב, כְּמוֹ שֶׁמְּסַיֵּם וְהוֹלֵךְ:",2,0],[14,4,"וּמָשׁ חֲצִי הָהָר צָפוֹנָה וְגוֹ׳. חֶצְיוֹ הַצְּפוֹנִי יָמוּשׁ מִמְּקוֹמוֹ וְיִמָּשֵׁךְ לְצַד צָפוֹן, וְכֵן מָצִינוּ חֶצְיוֹ נֶגְבָּה לְצַד דָּרוֹם. וְיִהְיֶה הַגַּיְא בֵּינֵיהֶם, רֹאשׁוֹ לְמִזְרָח וְסוֹפוֹ לְמַעֲרָב:",3,0],[14,5,"וְנַסְתֶּם גֵּיא הָרַי. יוֹנָתָן תִּרְגֵּם: ״וְיִסְתַּתֵּם גֵּיא הָרַי״. לְפִי שֶׁ״יְרוּשָׁלַיִם הָרִים סָבִיב לָהּ״ (תהלים קכה:ב), וְיֵשׁ גַּיְא בֵּין הַר שֶׁבַּצָּפוֹן וּבֵין הַר הַזֵּיתִים, וְכֵן בַּדָּרוֹם. וּכְשֶׁיִּמָּשֵׁךְ חֲצִי הַר הַזֵּיתִים אֵצֶל הַר שֶׁבִּצְפוֹנוֹ, יִסָּתֵם הַגַּיְא שֶׁבֵּינֵיהֶם, וְכֵן בַּדָּרוֹם:",1,0],[14,5,"כִּי יַגִּיעַ. גֹּבַהּ גַּיְא שֶׁהָיָה בֵּין הֶהָרִים:",2,0],[14,5,"אֶל אָצַל. אֶל גֹּבַהּ רָאשֵׁי הֶהָרִים שֶׁמִּכָּאן וּמִכָּאן. וְכֵן חִבְּרוֹ מְנַחֵם (ישעיהו מא:ט) ״וּמֵאֲצִילֶיהָ קְרָאתִיךָ״, וּפֵרוּשׁוֹ לְשׁוֹן גֹּבַהּ:",3,0],[14,5,"וְנַסְתֶּם. בִּרְאוֹתְכֶם הַמּוֹפֵת הַגָּדוֹל הַזֶּה:",4,0],[14,5,"כַּאֲשֶׁר נַסְתֶּם מִפְּנֵי הָרַעַשׁ. (יְשַׁעְיָהוּ ו:ד) ״וַיָּנֻעוּ אַמּוֹת הַסִּפִּים״ בְּיוֹם שֶׁנִּתְנַגַּע עֻזִּיָּהוּ:",5,0],[14,5,"כָּל קְדוֹשִׁים. מַלְאָכִים:",6,0],[14,6,"לֹא יִהְיֶה אוֹר יְקָרוֹת וְקִפָּאוֹן. יוֹנָתָן תִּרְגֵּם: ״לָא יְהֵי נְהוֹרָא אֶלָּהֵין עָדֵי וְגָלִיד יְהֵי נְהוֹרָא״. לֹא יִהְיֶה אוֹר נֹגַהּ, כִּי יְקָרוֹת וְקִפָּאוֹן יִהְיֶה. יְקָרוֹת – לְשׁוֹן ״כִּיקַר כָּרִים״ (תהלים לז:כ): הוּא כְּמִין אוֹר הַנִּרְאֶה שַׁחֲרִית עַל הֶהָרִים, וְכָלֶה וְהוֹלֵךְ:",1,0],[14,6,"וְקִפָּאוֹן. קָפוּי וְחָשׁוּךְ וְעָב כַּקֶּרַח שֶׁנִּקְפָּה וּמַגְלִיד, כְּמוֹ ״וְכַגְּבִינָה תַּקְפִּיאֵנִי״ (איוב י:י):",2,0],[14,7,"וְהָיָה יוֹם אֶחָד. וְהָיָה הַדָּבָר הַזֶּה יוֹם אֶחָד מִיּוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא הַיּוֹם יָדוּעַ שֶׁהוּא לַהֲכָנַת יִשְׁעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (פרקי דרבי אליעזר כח):",1,0],[14,7,"לֹא יוֹם וְלֹא לָיְלָה. לֹא אוֹר נֹגַהּ כְּאוֹר שֶׁל עוֹלָם הַבָּא, שֶׁנֶּאֱמַר: ״וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר וְגוֹמֵר״ (ישעיהו ל:כו):",2,0],[14,7,"וְלֹא לָיְלָה. וְלֹא עֵת צָרָה כְּצָרַת שִׁעְבּוּד גָּלֻיּוֹת שֶׁמִּקֹּדֶם, שֶׁיְּמֵי מְשִׁיחֵנוּ יִהְיוּ וְאֵין בָּהֶם שִׁעְבּוּד:",3,0],[14,7,"וְהָיָה לְעֵת עֶרֶב. קֹדֶם שֶׁיִּגָּמְרוּ אֶלֶף שָׁנָה יִהְיֶה אוֹר הַנֹּגַהּ וְכָל הַטּוֹב הָאָמוּר עַל יִשְׂרָאֵל (בראשית רבה ע:סב). וְכֵן תִּרְגֵּם יוֹנָתָן: ״לָא כִּנְהוֹר יוֹמָא וְלָא כִּקְבַל לֵילְיָא״:",4,0],[14,8,"וְהָיָה בַּיּוֹם הַהוּא. כְּשֶׁיִּבָּקַע הַר הַזֵּיתִים מִן הַמִּזְרָח לַמַּעֲרָב (זכריה יד:ד):",1,0],[14,8,"יֵצְאוּ מַיִם חַיִּים מִירוּשָׁלַ͏ִם. וְיֵלְכוּ לַמִּזְרָח דֶּרֶךְ אוֹתָהּ בְּקִיעָה עַד הַיָּם הַקַּדְמוֹנִי שֶׁהוּא לְמִזְרָחוֹ שֶׁל עוֹלָם קֵדְמָה. וְחֶצְיוֹ יִפְנֶה לַמַּעֲרָב אֶל יָם הַמַּעֲרָבִי. הוּא הַמַּעְיָן שֶׁנִּבָּא יוֹאֵל (יואל ד:יח) ״וּמַעְיָן מִבֵּית ה׳ יֵצֵא״, הוּא הַנַּחַל שֶׁנִּבָּא (יחזקאל מז:ד) ״וַיָּמָד אֶלֶף וַיַּעֲבִרֵנִי בַמַּיִם וְגוֹ׳״:",2,0],[14,9,"יִהְיֶה ה׳ אֶחָד. שֶׁכָּל הָאֻמּוֹת יַעַזְבוּ הַבְלֵיהֶם וְיוֹדוּ לוֹ שֶׁהוּא אֶחָד וְאֵין עִמּוֹ אֵל נֵכָר:",1,0],[14,9,"וּשְׁמוֹ אֶחָד. שֶׁיְּהֵא שְׁמוֹ נִזְכָּר בְּפִי כֻּלָּם:",2,0],[14,10,"יִסּוֹב כָּל הָאָרֶץ. יֵהָפֵךְ לִהְיוֹת כָּל הָאָרֶץ כַּעֲרָבָה, יִשְׁפְּלוּ הֶהָרִים וִיהִי כָּל הָעוֹלָם כֻּלּוֹ מִישׁוֹר (ישעיהו מ:ד), וִירוּשָׁלַיִם הַר כְּדֵי שֶׁתֵּרָאֶה גָּבוֹהַּ עַל הַכֹּל:",1,0],[14,10,"מִגֶּבַע לְרִמּוֹן נֶגֶב יְרוּשָׁלָ͏ִם. שָׁנִינוּ בְּתוֹסֶפְתָּא דְּסוֹטָה (תוספתא סוטה יא,יד): נֶגֶב יְרוּשָׁלִַם מִישׁוֹר הוּא, וְגֶבַע רִמּוֹן טְרָשִׁין וְקַרְקְשִׁין. וְכֵן פִּתְרוֹנוֹ: מִגֶּבַע לְרִמּוֹן, שֶׁהוּא מְקוֹם הָרִים, מִשָּׁם יַתְחִילוּ לִהְיוֹת נֶהְפָּכִין לַעֲרָבָה וּלְמִישׁוֹר, וְיִהְיוּ דוֹמִין לְנֶגֶב יְרוּשָׁלִַם, שֶׁהוּא מִישׁוֹר:",2,0],[14,10,"וְרָאֲמָה. מִתּוֹךְ שֶׁכָּל סְבִיבָהּ מִישׁוֹר, תֵּרָאֶה הִיא גְּבוֹהָָָה:",3,0],[14,10,"וְיָשְׁבָה תַּחְתֶּיהָ. בִּמְקוֹמָהּ:",4,0],[14,10,"עַד שַׁעַר הַפִּנִּים וּמִגְדַּל חֲנַנְאֵל. גַּם הוּא בִּמְקוֹמוֹ, וּמִשָּׁם יִמָּשֵׁךְ אֹרֶךְ הָעִיר עַד יִקְבֵי הַמֶּלֶךְ. תַּרְגּוּם יוֹנָתָן: ״שִׁיחֵי דְמַלְכָּא״, פושיי״ן בְּלַעַ״ז. וּכְמוֹ (בבא קמא נ:) שִׁיחִין וּמְעָרוֹת. וְכֵן כָּל יְקָבִים שֶׁבַּמִּקְרָא לְשׁוֹן שִׁיחִין הֵם: בּוֹר שֶׁלִּפְנֵי הַגַּת שֶׁהַיַּיִן זָב לְתוֹכוֹ. וּמִדְרַשׁ אַגָּדָה: יִקְבֵי מֶלֶךְ יָם אוֹקְיָנוֹס, שֶׁתַּגִּיעַ יְרוּשָׁלַיִם עַד סוֹף כָּל הָעוֹלָם. יְקָבִים שֶׁחֲצָבָם מֶלֶךְ מַלְכֵי הַמְּלָכִים:",5,0],[14,11,"וְחֵרֶם לֹא יִהְיֶה. הָעִיר עוֹד:",1,0],[14,12,"הָמֵק בְּשָׂרוֹ וְהוּא עוֹמֵד. זֶה נִפּוּל אֵיבָרִים:",1,0],[14,13,"תִּהְיֶה מְהוּמַת ה׳ רַבָּה בָּהֶם. לְעַרְבֵּב חָכְמָתָם לְהָפְכָם לְשִׁגָּעוֹן:",1,0],[14,13,"וְהֶחֱזִיקוּ אִישׁ יַד רֵעֵהוּ. יֹאחֵז בּוֹ לְהָרְגוֹ:",2,0],[14,13,"וְעָלְתָה יָדוֹ. כָּל דְּאַלִּים גָּבַר (בבא בתרא לד:):",3,0],[14,14,"וְגַם יְהוּדָה. עַל כָּרְחָהּ תִּלָּחֵם עַל יִשְׂרָאֵל:",1,0],[14,15,"כַּמַּגֵּפָה הַזֹּאת. הַמְפֹרֶשֶׁת לְמַעְלָה ״הָמֵק בְּשָׂרוֹ״:",1,0],[14,16,"אֶת חַג הַסֻּכּוֹת. כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמַסֶּכֶת עֲבוֹדָה זָרָה: מִצְוָה קַלָּה יֵשׁ לִי וְסֻכָּה שְׁמָהּ, כִּדְאִיתָא בִּשְׁמַעְתָּא רִאשׁוֹנָה (עבודה זרה ג.):",1,0],[14,17,"הַגָּשֶׁם. גְּשָׁמִים מַמָּשׁ, לְהַצְמִיחַ פֵּרוֹת אַרְצָם. וּמָה רָאָה לִגְזֹר עֲלֵיהֶם עֲצִירַת גְּשָׁמִים? לְפִי שֶׁמִּצְוֹת הֶחָג עַל הַגְּשָׁמִים הֵם – אַרְבַּעַת מִינִים שֶׁבַּלּוּלָב וְנִסּוּךְ הַמַּיִם – לְרַצּוֹת עַל הַמַּיִם, עַל שֶׁהֶחָג זְמַן גִּשְׁמֵי שָׁנָה הוּא. וְאֵלּוּ הַמְפַקְפְּקִין בְּחַג הַסֻּכּוֹת, לֹא עֲלֵיהֶם יִהְיֶה הַגָּשֶׁם. כָּךְ לָמַדְתִּי בְּתוֹסֶפְתָּא דְּסֻכָּה (תוספתא סוכה ג:יח):",1,0],[14,18,"וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה. וְהֵן אֵין צְרִיכִים לִגְשָׁמִים, שֶׁנִּילוּס עוֹלֶה וּמַשְׁקֶה אוֹתָם:",1,0],[14,18,"וְלֹא עֲלֵיהֶם. תִּהְיֶה הַגֶּשֶׁם שֶׁלָּהֶם, כְּלוֹמַר: לֹא יַשְׁקֶה אוֹתָם נִילוּס. וְכֵן תִּרְגֵּם יוֹנָתָן: ״לָא עֲלֵיהוֹן יִסַּק נִילוּס״:",2,0],[14,18,"תִּהְיֶה הַמַּגֵּפָה. שֶׁל רָעָב:",3,0],[14,18,"אֲשֶׁר יִגֹּף ה׳‏. זֹאת תִּהְיֶה עֹנֶשׁ מִצְרַיִם וְעֹנֶשׁ כָּל הָעוֹבְדֵי כּוֹכָָבִים וּמַזָָָָּלוֹת, כְּמוֹ שֶׁאָמַר לֹא עֲלֵיהֶם יִהְיֶה הַגֶּשֶׁם:",4,0],[14,20,"מְצִלּוֹת הַסּוּס. עַל הַנְּקִישׁוֹת שֶׁתּוֹלִין לַסּוּס לְנוֹי בֵּין עֵינָיו (פסחים נ.), אַף אוֹתָן יַקְדִּישׁוּ לַעֲשׂוֹת כְּלֵי שָׁרֵת לַמִּזְרָקִים לַדָּם וְלַסִּירוֹת לְבַשֵּׁל בְּשַׂר זְבָחִים לָרֹב:",1,0],[14,20,"וְהָיָה הַסִּירוֹת. שֶׁהֵם הָיוּ לְדַשֵּׁן (אֶת הַדֶּשֶׁן) אַף הֵם יִהְיוּ שֶׁל זָהָב וְשֶׁל כֶּסֶף כַּמִּזְרָקִים אֲשֶׁר לִפְנֵי הַמִּזְבֵּחַ:",2,0],[14,20,"מְצִלּוֹת הַסּוּס. טַנְטִינִי״ר בְּלַעַ״ז:",3,0],[14,21,"וְלֹא יִהְיֶה כְנַעֲנִי. לֹא יִצְטָרְכוּ לִסְחוֹר, כְּמוֹ (ישעיהו כג:ח) ״כִּנְעָנֶיהָ נִכְבַּדֵּי אָרֶץ״. דָּבָר אַחֵר: אֵין כָּאן עָנִי:",1,0]]);
